export const CARDS = [
  // ─── Moment cards (20) ───
  { id: 'm01', type: 'moment', category: 'morning', title: 'The morning getting ready battle', seoTitle: "Why won't my ADHD child get ready in the morning?", answerBlock: "The ADHD prefrontal cortex is weakest in the first 30 minutes of waking, so task initiation stalls even when your child can see what needs doing. Their brain cannot generate the dopamine signal to start on demand. Stop repeating the instruction. Walk over, give one concrete action like shoes, put the first thing in their hand, and stay close without talking." },
  { id: 'm02', type: 'moment', category: 'homework', title: 'The homework explosion', seoTitle: "Why does homework turn into a meltdown every day?", answerBlock: "Your child arrives home with an empty tank, and homework needs a prefrontal cortex that is already offline. A raised voice activates the amygdala and makes starting neurologically harder, not easier. Stop the fight before restarting the work. Lower the temperature, offer food and ten minutes of something they enjoy, then sit nearby doing your own work. Body-doubling restarts a stalled brain." },
  { id: 'm03', type: 'moment', category: 'after-school', title: 'The after-school collision — their decompression meets your mask drop', seoTitle: "Why do my ADHD kid and I clash the moment we get home?", answerBlock: "You have both been masking all day, and masking drains the regulatory reserves that keep you calm. Two depleted nervous systems meeting in a doorway will amplify each other, and the collision is structural, not bad parenting. Get low stimulus for five minutes first: sit, drink something, delay any conversation until you have landed. Put food down for your child and let them decompress without questions." },
  { id: 'm04', type: 'moment', category: 'bedtime', title: 'The bedtime battle', seoTitle: "Why is bedtime such a battle for my ADHD child?", answerBlock: "ADHD sleep runs late and restless, and when stimulation stops the default mode network switches on, so a dark quiet room makes the brain race rather than settle. Your own regulation is also at its lowest point of the day. Shorten the routine, use fewer words, and stay physically close instead of calling instructions from the doorway. An audiobook or white noise gives the brain something to track." },
  { id: 'm05', type: 'moment', category: 'out-and-about', title: 'The car journey meltdown', seoTitle: "Why does my ADHD child melt down in the car?", answerBlock: "A car is an inescapable sensory container, and the ADHD sensory system has weaker gating, so noise, movement and confinement all arrive at full volume with nowhere to go. The meltdown is overwhelm, not defiance. Reduce the input: turn off the music, open a window, stop talking. Say one calm sentence, then stay quiet. If it is safe, pull over for two minutes of stillness." },
  { id: 'm06', type: 'moment', category: 'out-and-about', title: 'The public meltdown', seoTitle: "How do I handle my ADHD child's meltdown in public?", answerBlock: "ADHD brains carry heightened rejection sensitivity, so the perceived judgement of strangers fires the same circuits as real criticism while you also manage your child's overwhelm. That double load pushes you to be harsher or to cave. Move to a quieter space before you address anything: outside, the car, a corner, anywhere lower stimulus. Then use minimal language and let the meltdown complete its natural arc somewhere safe." },
  { id: 'm07', type: 'moment', category: 'emotional-escalation', title: 'When their meltdown triggers yours', seoTitle: "Why do I lose it when my child has a meltdown?", answerBlock: "Limbic resonance means one dysregulated nervous system entrains the one beside it, so your child's meltdown pulls your amygdala along before you can decide otherwise, and in ADHD the runway between trigger and reaction is shorter. You cannot regulate them while flooded. Your only job is to stop escalating: step back, go quiet, lower your voice and slow your movements. Their nervous system will begin to follow yours down." },
  { id: 'm08', type: 'moment', category: 'emotional-escalation', title: "When the escalation won't stop and neither of you can", seoTitle: "How do I stop a fight with my ADHD child spiralling?", answerBlock: "ADHD brains have a strong drive for cognitive closure, so an unresolved argument creates a neurological itch you both keep scratching, and more talking makes it worse. Two brains seeking closure never find it inside the argument. Someone has to stop first, and it will not be them. End it with one sentence, stay physically near in silence, and return to the issue once both of you are regulated." },
  { id: 'm09', type: 'moment', category: 'emotional-escalation', title: 'When they lose it over something tiny', seoTitle: "Why does my ADHD child overreact to tiny things?", answerBlock: "ADHD emotions arrive at full intensity with no dimmer switch, and the tiny trigger is usually the last input on top of accumulated load the prefrontal cortex can no longer moderate. The small thing was never the real thing. Do not point out that it was small, that only adds shame. Validate the feeling, offer food, and give space for the intensity to pass." },
  { id: 'm10', type: 'moment', category: 'instructions', title: "When they won't follow instructions or seem to be ignoring you", seoTitle: "Why does my ADHD child ignore what I tell them?", answerBlock: "What looks like ignoring is usually a working memory failure, not a hearing problem. ADHD working memory holds fewer items for less time, so an instruction called across the room drops out before the motor system can act on it. Get within arm's reach, say their name once, give one instruction, then stay near for thirty seconds. Physical proximity bridges the gap that shouting never will." },
  { id: 'm11', type: 'moment', category: 'hyperfocus', title: "When they're hyperfocused and won't stop", seoTitle: "Why can't my ADHD child stop when they hyperfocus?", answerBlock: "Hyperfocus is not a choice. The ADHD default mode and task-positive networks are anti-correlated, so when one locks on, switching off needs executive function that may not be available, and sudden interruption feels like an attack on focus and triggers a fight. Start a countdown five minutes out, then two minutes, then time. Build a bridge to what comes next so the anticipation helps the brain begin to disengage." },
  { id: 'm12', type: 'moment', category: 'siblings', title: 'When sibling conflict explodes', seoTitle: "How do I stop my ADHD kids fighting each other?", answerBlock: "Two dysregulated children amplify each other, and ADHD impulse control is the most consistently impaired executive function, so the urge to hit, grab or scream fires before consequences register. This is a fire to separate, not a conflict to mediate. Put one child per room, or your body between them, and silence it first. Adjudicate fairness later, once there are two calm nervous systems instead of one amplified one." },
  { id: 'm13', type: 'moment', category: 'siblings', title: 'When they get physical with their sibling', seoTitle: "What do I do when my ADHD child hits their sibling?", answerBlock: "Physical aggression in ADHD is usually impulsive, not planned. The prefrontal cortex that should inhibit the action between impulse and hit did not fire fast enough, because that brake is the most impaired function. Move your body between them now, calm and decisive, rather than shouting from across the room. Separate first, keep both children safe, and save the conversation for after everyone has settled. They know hitting is wrong." },
  { id: 'm14', type: 'moment', category: 'after-school', title: 'Fine at school, falling apart at home', seoTitle: "Why is my ADHD child fine at school but not at home?", answerBlock: "School provides novelty, structure and social demand that scaffold the ADHD brain through the day using a hyperfocus-under-pressure mechanism. Home has none of that scaffolding, so the mask drops and the held-in load releases. The collapse is the cost of performing, not a sign your parenting is failing. Validate the effort, keep demands low, offer food, and let them decompress. They fall apart with you because they feel safe." },
  { id: 'm15', type: 'moment', category: 'communication', title: 'When you said the thing that caused real damage', seoTitle: "I said something hurtful to my kid and feel terrible.", answerBlock: "ADHD impulsivity applies to speech as well as action, so the words left your mouth before your prefrontal cortex could filter them. A child's amygdala reacts to tone and volume before content, so their brain is now processing the emotional hit, not the message. Stop adding words. Say one brief line: that was wrong, I'm sorry. Do the fuller repair later. The return to normal is the real repair." },
  { id: 'm16', type: 'moment', category: 'communication', title: 'When you lectured instead of stopping', seoTitle: "Why does lecturing my ADHD child never seem to work?", answerBlock: "Sustained attention to non-stimulating verbal input is one of the hardest tasks for an ADHD brain, and as emotional intensity rises executive function drops further, so your child stopped processing the content minutes ago and is only managing the experience of being lectured. Everything past the first point is for you, not them. Say the one thing that matters, once, then stop. The lesson lands tomorrow in two minutes." },
  { id: 'm17', type: 'moment', category: 'communication', title: 'When you were too hard on your kid for something you do yourself', seoTitle: "I punished my ADHD child for something I do too.", answerBlock: "Pattern recognition is strong in ADHD, so seeing your own traits in your child and correcting them for it creates real cognitive dissonance. For the child it stacks rejection sensitivity on top of the unfairness. You do not have to fix it instantly, but name it later: I was hard on you for something I struggle with too, that wasn't fair. Honesty restores what the correction cost." },
  { id: 'm18', type: 'moment', category: 'losing-forgetting', title: 'When they keep losing or forgetting things', seoTitle: "Why does my ADHD child keep losing and forgetting things?", answerBlock: "Losing and forgetting are working memory failures, not attitude. Object permanence is weaker in ADHD, so items out of direct sight genuinely stop existing in working memory and the brain stops tracking them. Blame will not locate the thing or prevent the next time. Help find it calmly first, then build an external system: labels, hooks, transparent containers, one designated spot. Reduce the demand instead of asking for more." },
  { id: 'm19', type: 'moment', category: 'competition', title: "When they can't handle losing", seoTitle: "Why can't my ADHD child cope with losing a game?", answerBlock: "ADHD emotional regulation is deeply impaired, and losing triggers not just disappointment but a rejection sensitivity response, so it lands as evidence they are not good enough rather than a lost game. Telling them it is just a game is unprocessable mid-storm. Acknowledge the feeling: I can see losing feels really bad right now. Ride out the intensity, stay near, and teach sportsmanship once they are calm." },
  { id: 'm20', type: 'moment', category: 'attention', title: 'When you checked your phone and they acted out to get you back', seoTitle: "Why does my kid act out when I check my phone?", answerBlock: "Your child's attachment system is highly tuned to your availability, and an ADHD child who feels less sure of holding adult attention is especially sensitive when it shifts away. The acting out is a bid to bring you back, not manipulation. The most efficient response is the one they seek: put the phone face down, give thirty seconds of eye contact and warmth, then address the behaviour calmly." },
  { id: 'm21', type: 'moment', category: 'screen-time', title: 'The screen-time handoff', seoTitle: "Why does my ADHD child melt down when screens go off?", answerBlock: "Screens deliver rapid dopamine cycles the ADHD brain locks onto, so switching one off creates a neurological deficit, and the irritability that follows is genuine withdrawal, not entitlement. Going from high stimulation to nothing is the hardest transition. Do not negotiate or turn the screen back on. Name what comes next, not what is ending, and offer a snack, movement or something for their hands to bridge the gap." },

  // ─── Parent-only cards (21) ───
  { id: 'p01', type: 'parent', category: 'shame', title: 'The shame spiral after losing it', seoTitle: "Why can't I stop feeling guilty after yelling at my kid?", answerBlock: "ADHD comes with heightened rejection sensitivity and a longer emotional hangover, so feelings take longer to return to baseline and the shame stays activated well after the incident. The rumination feels like accountability but it is consuming the energy the repair actually needs. Set a time limit on the guilt, then act. A calm two-sentence repair once you are settled is what changes the relationship, not feeling worse first." },
  { id: 'p02', type: 'parent', category: 'shame', title: "Repeating your own parents' behaviour", seoTitle: "Why do I catch myself parenting like my own parents?", answerBlock: "Parenting scripts are stored in procedural memory through mirror neurons and implicit learning, so they fire automatically under stress, exactly when the prefrontal cortex that would choose differently goes offline. Hearing the echo and recognising it is already different from what your parent did, and the pattern now has a gap. Pause the moment: I need a second. Then come back and respond differently. Awareness is the opening." },
  { id: 'p03', type: 'parent', category: 'shame', title: 'Overcorrecting with affection right after losing it', seoTitle: "Why do I smother my kid with affection after losing it?", answerBlock: "After a dysregulation event the ADHD brain often swings to the opposite extreme, and guilt drives a repair urge far bigger than what your child needs, so the flood of warmth is really asking them to reassure you. It can leave them unsure which version of you to trust. Keep the repair brief and calm: I'm sorry I got so upset, let's do something ordinary. Then do the ordinary thing." },
  { id: 'p04', type: 'parent', category: 'partner', title: 'Contradicting your partner in front of the kids', seoTitle: "Why do I contradict my partner in front of the kids?", answerBlock: "ADHD impulsivity applies to disagreement too, so your brain flagged something in your partner's approach and responded before executive function could weigh the need for a united front. The child just learned the boundary has a gap, which becomes a negotiation opening that undermines both of you. Hold the current position out loud, even if it is not your preference. Raise the disagreement privately later, then present one line together." },
  { id: 'p05', type: 'parent', category: 'partner', title: 'Caving on a boundary your partner just set', seoTitle: "Why do I cave when my child pushes hard enough?", answerBlock: "ADHD brains respond more to immediate emotional pressure than to abstract future consequences, so the distress in front of you is neurologically louder than the principle behind the boundary, and giving in feels like relief. The cost is your child learning that sustained pressure works. Do not double down to save face. Re-establish the boundary later, calmly. Walking it back honestly beats enforcing something disproportionate." },
  { id: 'p06', type: 'parent', category: 'partner', title: 'Snapping at your partner when it was really about your kid', seoTitle: "Why do I snap at my partner over my kid's behaviour?", answerBlock: "Emotional dysregulation in ADHD does not always hit the source. With the prefrontal cortex impaired, the emotion finds the nearest outlet, often the safest relationship, so your partner absorbs frustration that was really about the child or the day. Over time that erodes the co-parenting relationship. Contain it in the moment rather than processing in front of the child, then acknowledge it after: that wasn't about you, I'm sorry." },
  { id: 'p07', type: 'parent', category: 'partner', title: 'Losing your temper at a teacher or another parent', seoTitle: "Why did I lose my temper at my child's teacher?", answerBlock: "ADHD rejection sensitivity means perceived criticism registers in the amygdala at threat level, so a teacher's concern about your child can land as an attack on your parenting and the defensive response fires before reason catches up. The relationship took damage that needs repair. Take twenty-four hours before any follow-up, then reach out calmly: I was more heated than was useful yesterday, I would like to have the conversation differently." },
  { id: 'p08', type: 'parent', category: 'misfires', title: 'Dragging something old into a new moment', seoTitle: "Why do I drag up old fights in a new argument?", answerBlock: "ADHD working memory is unreliable for logistics, but emotionally significant memories are stored differently and stay accessible, so unresolved incidents get triggered by similar moments and your brain pattern-matches across time. Now your child is defending against today and last week at once, and can only process one. Catch it and drop the old thread: that is old, what is the issue right now? Stay in the present." },
  { id: 'p09', type: 'parent', category: 'misfires', title: "Taking the day's frustration out on your kid", seoTitle: "Why do I take my bad day out on my child?", answerBlock: "Regulatory capacity is a depletable resource, and after a full day managing impulses the prefrontal cortex has less left, so your reaction is the size of the whole day, not what your child did. They only know you lost it over something small. One breath and one reset: this isn't their fault. If it already landed, name it: I had a hard day, that wasn't about you." },
  { id: 'p10', type: 'parent', category: 'withdrawal', title: 'Shutting down and going cold', seoTitle: "Why do I shut down and go cold on my kid?", answerBlock: "When load exceeds threshold, some ADHD nervous systems default to shutdown rather than escalation, so going quiet is a protection response, not a choice. The shutdown prevents escalation but gives your child none of the connection they need. You cannot force presence, but you can signal you are still there. One sentence: I need a few minutes, I'm here. Then mark your return: I'm back now." },
  { id: 'p11', type: 'parent', category: 'withdrawal', title: 'Leaving when you should have stayed', seoTitle: "Why do I walk away when my kid needs me to stay?", answerBlock: "Withdrawal is a nervous system protection response: the ADHD brain that defaults to shutdown is avoiding further damage, but it leaves out the connection and repair the moment needed. Your child may read the absence as punishment or abandonment. You cannot undo the leaving, but you can return, and a quiet warm return beats staying away. Go back in: I'm here now. You do not have to explain it." },
  { id: 'p12', type: 'parent', category: 'withdrawal', title: "Pretending you didn't see what happened", seoTitle: "Why do I pretend I didn't see my kid act out?", answerBlock: "The ADHD executive function system sometimes triages by avoidance, so when engaging feels costlier than ignoring, the brain selects the path with less demand. This is a depleted regulatory system self-preserving, not laziness. The gap between what your child needed and what you could give is a capacity issue, not a moral failure. Address it when you have the capacity: I saw what happened, we will talk about it." },
  { id: 'p13', type: 'parent', category: 'withdrawal', title: "Letting something go you knew you shouldn't", seoTitle: "Why do I let boundaries slide by the end of the day?", answerBlock: "Consistent boundary enforcement runs on sustained executive function, and every boundary depletes the same prefrontal cortex resources used all day, so by evening the system cannot hold the line. Inconsistency confuses children, especially ADHD children who need predictable environments to regulate. The fix is not more willpower but fewer boundaries held more consistently. Pick three that matter, let the rest go, and reinstall the limit clearly before next time." },
  { id: 'p14', type: 'parent', category: 'executive-function', title: 'Forgetting something that genuinely mattered to your kid', seoTitle: "Why do I forget things that really matter to my kid?", answerBlock: "Because ADHD working memory holds fewer items for shorter durations, and parenting runs on an enormous invisible load of dates, promises, and routines that all live in exactly the part of your brain that struggles most. Forgetting is not a sign you stopped caring. Give one thing one external anchor, written somewhere physically visible in the space you will need it, not on your phone." },
  { id: 'p15', type: 'parent', category: 'executive-function', title: 'Losing the paperwork, the date, the appointment', seoTitle: "Why do I keep losing paperwork and missing appointments?", answerBlock: "Paper tasks are the hardest for an ADHD brain because they carry no notification and no prompt. They exist only in working memory, which holds fewer items for shorter durations, so the form or the date quietly drops out. The fix is not trying harder to remember, it is reducing what depends on memory. Photograph the form, make the calendar entry immediately, and keep one physical spot for papers." },
  { id: 'p16', type: 'parent', category: 'executive-function', title: 'Starting to help and getting distracted before you finished', seoTitle: "Why do I get distracted while helping my child?", answerBlock: "ADHD attention is interest-driven, not importance-driven. Partway through helping, the task lost its novelty signal and your dopamine system followed the next input. This is not a choice or a measure of how much your child matters. The repair is the return. Go back, name it plainly, and finish. Say 'I got distracted. Let me come back to this,' then stay with it until it is done." },
  { id: 'p17', type: 'parent', category: 'executive-function', title: "Cancelling something you'd promised because you got overwhelmed", seoTitle: "Why do I overpromise my kid then have to cancel?", answerBlock: "ADHD brains overcommit because the future feels abstract while the wish to please is immediate. The promise came from a version of you that did not account for the executive function cost of following through, and that gap between intention and capacity is the core ADHD experience. Tell your child now rather than letting them find out. Acknowledge the impact, deliver the smallest version you can, and make fewer promises." },
  { id: 'p18', type: 'parent', category: 'adhd-specific', title: 'Medication timing making home worse than work', seoTitle: "Why am I calmer at work than with my own kids?", answerBlock: "Stimulant medication raises dopamine and norepinephrine in the prefrontal cortex, so when it wears off your regulatory capacity drops measurably and the rebound can make you more irritable than your unmedicated baseline. Home gets the worst version of your day because of timing, not because of how you feel about them. Step back fifteen minutes before hard conversations, and ask your prescriber about extended-release or an afternoon booster." },
  { id: 'p19', type: 'parent', category: 'adhd-specific', title: 'Oversharing your own problems with your child', seoTitle: "Why do I overshare my problems with my child?", answerBlock: "ADHD impulsivity includes verbal impulsivity. The filter between thought and speech is thinner, and in an intense moment the executive function that asks 'is this appropriate for a child' is offline, so the relief of saying it beats the judgment. A short repair is enough. Say 'I told you something that is my problem, not yours. You do not need to worry. I will handle it.'" },
  { id: 'p20', type: 'parent', category: 'adhd-specific', title: "Using your kid's ADHD as cover for your own", seoTitle: "Why do I blame my kid's ADHD for my own mistakes?", answerBlock: "Attribution errors are common in ADHD families. When parent and child share traits, it is easy to project your own executive function slip onto the child's diagnosis, so their ADHD becomes a convenient explanation for chaos yours also created. Left unchecked, your child absorbs blame that is not theirs and it distorts how they see themselves. Separate what is yours from what is theirs, honestly." },
  { id: 'p21', type: 'parent', category: 'adhd-specific', title: 'Freezing when both kids needed you at the same time', seoTitle: "Why do I freeze when both my kids need me at once?", answerBlock: "ADHD executive function is especially impaired under divided attention, and switching between two urgent demands can exceed the bandwidth you have. The freeze is a processing bottleneck, not indifference. You cannot split, so triage. Handle safety first, then the youngest or most distressed, then the other. Name the constraint out loud: 'I can only help one person at a time. I am coming to you next.'" },
  { id: 'p22', type: 'parent', category: 'avoidance', title: 'The doom scroll instead of starting bedtime', seoTitle: "Why can't I stop scrolling and start my kid's bedtime?", answerBlock: "You can see the clock and still cannot begin, because the hardest part is starting, and the brain will not hand you a 'ready' signal on demand. Motion comes before motivation, not after. Put the phone face down beside you, not away. Then stand up. Once you are standing, walk to the bathroom and start the water. The rest of bedtime follows the movement." },

  // ─── Kid-only cards (10) ───
  { id: 'k01', type: 'kid', category: 'organisation', title: 'Losing things constantly', seoTitle: "Why does my ADHD child lose things all the time?", answerBlock: "Object permanence is weaker in ADHD. Items that leave your child's line of sight genuinely stop existing in their working memory, so they cannot track what they cannot see. This is a memory limitation, not carelessness, and punishing it does not improve it. Build external systems that make the right place obvious. Hooks at eye level, labels, and clear containers instead of drawers carry the load memory keeps dropping." },
  { id: 'k02', type: 'kid', category: 'organisation', title: 'Forgetting things constantly', seoTitle: "Why does my ADHD child forget things over and over?", answerBlock: "ADHD working memory holds fewer items for shorter durations, so 'remember your lunch' asks your child to carry a future action across a string of distracting transitions, and each transition is a chance for it to drop out. It was heard and lost, not ignored. Put the reminder where the action happens. A visual checklist on the door they walk through beats anything that depends on remembering." },
  { id: 'k03', type: 'kid', category: 'sensory', title: 'Sensory meltdowns — food, clothes, noise, touch', seoTitle: "Why does my child melt down over socks, food, or noise?", answerBlock: "ADHD frequently co-occurs with sensory processing differences. Inputs a neurotypical system filters out arrive at full intensity, so the sock seam, food texture, or noise really is the loudest signal in your child's body, and they cannot turn it down. The meltdown is distress, not manipulation. Remove or modify the input where you can rather than asking them to tolerate it, and validate: 'I can see that really bothers you.'" },
  { id: 'k04', type: 'kid', category: 'sensory', title: "Won't eat most things", seoTitle: "Why does my ADHD child refuse most foods?", answerBlock: "ADHD sensory sensitivity extends to taste, texture, temperature, and smell, so food aversions are neurological, not fussiness. Their nervous system rejects inputs that register as genuinely unpleasant, and forcing a triggering food fires the same alarm circuits as real threat. Pressure only deepens it. Put one safe food on every plate, make no comment on what they left, and offer low-pressure exposure over weeks." },
  { id: 'k05', type: 'kid', category: 'sensory', title: "Can't sit still at dinner", seoTitle: "Why can't my ADHD child sit still at the dinner table?", answerBlock: "The ADHD nervous system needs more sensory and motor input to reach optimal arousal, so sitting still is the opposite of what their body requires. The fidgeting, chair-tipping, and kicking are self-regulation, not defiance. Meet the movement need instead of fighting it. A wobble cushion, standing at the table, or a fidget tool works, and shorter meals with permission to move beat forced stillness." },
  { id: 'k06', type: 'kid', category: 'sensory', title: 'Impulsive physical behaviour — running, climbing, roughhousing', seoTitle: "Why does my ADHD child run and climb on everything?", answerBlock: "ADHD hyperactivity is dopamine-seeking. The motor cortex is under-stimulated and your child self-medicates through movement, so the impulse to run, jump, or climb arrives before the prefrontal cortex can judge whether it fits. Suppressing it does not lower the drive, it builds pressure that releases less controllably later. Channel the movement instead. Redirect now with 'Outside, you can run there,' and designate places where big movement is welcome." },
  { id: 'k07', type: 'kid', category: 'emotional', title: 'Falling apart over perceived failure or criticism', seoTitle: "Why does my ADHD child fall apart over small criticism?", answerBlock: "ADHD emotional regulation offers no dimmer switch, so perceived failure triggers not just disappointment but a rejection sensitivity response, a feeling of being exposed as not good enough. By age twelve a child with ADHD may have received twenty thousand more negative messages than their peers, so the reaction reflects experience, not personality. Validate first: 'That is really upsetting.' Have the real conversation only once they are regulated." },
  { id: 'k08', type: 'kid', category: 'school', title: 'School refusal or school anxiety', seoTitle: "Why does my ADHD child refuse to go to school?", answerBlock: "School demands sustained attention, impulse suppression, social navigation, and executive function for six straight hours, which for an ADHD brain is a marathon run in a body built for sprints. The refusal is their nervous system anticipating exhaustion, not laziness. Identify the specific stressor, a teacher, a subject, the noise, the transitions, because reducing one demand often makes the whole day manageable. Contact the school before nine." },
  { id: 'k09', type: 'kid', category: 'social', title: 'Saying the wrong thing at the wrong moment', seoTitle: "Why does my child blurt out the wrong thing?", answerBlock: "ADHD verbal impulsivity means thoughts become words before the social filter can assess them. The gap between thinking it and saying it is too short to weigh whether it is kind, appropriate, or well-timed, so this is a failure to inhibit, not rudeness. They usually know the instant it lands. Skip the public correction and hold a brief private debrief later. 'What happened there?' lets them process without humiliation." },
  { id: 'k10', type: 'kid', category: 'social', title: 'Lying', seoTitle: "Why does my ADHD child lie even about small things?", answerBlock: "ADHD children lie more often, but the mechanism is usually avoidant, not manipulative. The truth carries a consequence that feels overwhelming, and the prefrontal cortex cannot weigh long-term trust against short-term relief, so the lie is the path of least immediate resistance. Punishment does not fix this, making honesty safe does. Reduce the explosion that follows the truth, and mean it when you say 'Thank you for telling me.'" },
  { id: 'k11', type: 'kid', category: 'emotional', title: 'The friendship fallout they keep having', seoTitle: "Why does my ADHD child keep losing friendships?", answerBlock: "ADHD social processing runs slower. Your child misses the cue to stop talking, the signal a joke went too far, the moment another kid needed space, because the social operating system runs on different timing. They are not bad at friendship, they are running social software on slower hardware. Help them see the pattern without blame, remember one good friendship beats popularity, and give steady validation." },

  // ─── NEW MOMENT CARDS (25) ───
  { id: 'm22', type: 'moment', category: 'medication', title: 'The 5pm crash when the meds wear off', seoTitle: "Why does my ADHD child crash when the meds wear off?", answerBlock: "Stimulant medication raises dopamine in the prefrontal cortex all day, and when it clears, dopamine dips below the pre-medication baseline for a while. During that rebound your child is briefly less regulated than when completely unmedicated, so the crash is pharmacological withdrawal, not a mood swing. Do not teach or reason during it. Lower demands for thirty to sixty minutes, offer a snack, and keep transitions minimal." },
  { id: 'm23', type: 'moment', category: 'medication', title: 'They\'re hungry and feral now the meds are gone', seoTitle: "Why is my ADHD child starving after their meds wear off?", answerBlock: "Stimulants suppress appetite by raising dopamine and norepinephrine, which quiet the hunger signal all day. When the medication clears, that signal returns at full intensity, often stronger because the body has been under-fuelled since morning, and it lands on a system already in rebound. This is genuine hunger, not greed. Feed them without commentary on quantity. Protein and complex carbohydrates stabilise blood sugar fastest, so favour a protein-heavy snack." },
  { id: 'm24', type: 'moment', category: 'transitions', title: 'We\'re going to be late again and they\'re moving in slow motion', seoTitle: "Why does my ADHD child move so slowly when we're late?", answerBlock: "Time blindness means the passage of time is not felt internally, so 'five minutes until we leave' is an abstract idea, not an experienced reality. Your child cannot gauge it, and this is one of the most consistent ADHD impairments. 'Hurry up' adds pressure without speed. Walk to them, give one concrete action like 'Shoes on, now,' set a visual timer, and cut the words between you and the door." },
  { id: 'm25', type: 'moment', category: 'transitions', title: 'Turning off the video game turned into a war', seoTitle: "Why does turning off the game cause a huge meltdown?", answerBlock: "Games deliver rapid, predictable dopamine cycles that match what the ADHD brain craves, so switching the screen off creates an instant dopamine deficit. Stopping is not a preference, it is a neurological transition needing executive function their evening brain may not have, and the rage is withdrawal, not entitlement. Warn before the end, put a timer on the screen itself, and give them a next activity to move toward." },
  { id: 'm26', type: 'moment', category: 'safety', title: 'They bolted in the parking lot and my heart stopped', seoTitle: "Why did my ADHD child bolt in the parking lot?", answerBlock: "The impulse to run reached the motor cortex before the safety assessment could fire. The ADHD prefrontal cortex is the last region to mature and the first offline under excitement, so the bolt was an unfiltered impulse, not a decision to be dangerous. Breathe first, they are safe now. Hold their hand and say less. The safety conversation lands tonight when you are both calm, not while you are shaking." },
  { id: 'm27', type: 'moment', category: 'safety', title: 'They climbed something dangerous before I could blink', seoTitle: "Why does my ADHD child climb dangerous things?", answerBlock: "Impulse-driven risk-taking skips the risk-assessment step. The thrill signal reaches the motor system before the 'is this safe' evaluation in the prefrontal cortex can fire, so your child did not ignore the danger, they did not perceive it in time. Secure them first and check for injury. Save the safety teaching for later, delivered calmly with concrete language: 'That shelf can fall. Falling from that height breaks bones.'" },
  { id: 'm28', type: 'moment', category: 'transitions', title: 'The whole day fell apart the second the routine changed', seoTitle: "Why does my ADHD child unravel when routine changes?", answerBlock: "ADHD brains lean heavily on external structure to cover internal executive function gaps. When the routine breaks, every transition, decision, and impulse it quietly managed becomes a conscious demand, so unstructured time is a load, not a gift. Lower your expectations before the meltdown, not after. Pick the three things that matter and let the rest go, then build a micro-routine of three steps written where they can see it." },
  { id: 'm29', type: 'moment', category: 'sensory', title: 'The meltdown started over food being wrong', seoTitle: "Why does my child melt down when food looks wrong?", answerBlock: "ADHD sensory processing treats unexpected input as threat, so toast cut the wrong way, foods touching, or an unfamiliar texture triggers alarm rather than preference. The rigidity is the nervous system trying to control an unpredictable environment, and the deviation feels like a violation of safety. Do not argue. Replace the food if you can, and if you cannot, acknowledge it: 'I can see that is really bothering you.'" },
  { id: 'm30', type: 'moment', category: 'sensory', title: 'Getting dressed became a screaming match over a sock seam', seoTitle: "Why does a sock seam start a meltdown every morning?", answerBlock: "Tactile sensitivity in ADHD means textures, seams, tags, and pressure points register at far higher intensity than for a neurotypical child. The seam you cannot even feel is dominating their whole sensory experience, and they cannot think about anything else until it is resolved. This is real sensation, not manipulation. Remove the input rather than teaching tolerance. Buy seamless socks, cut every tag, and turn clothes inside out if needed." },
  { id: 'm31', type: 'moment', category: 'hygiene', title: 'Bath, shower, or teeth-brushing is a nightly fight', seoTitle: "Why is brushing teeth or bath time a nightly fight?", answerBlock: "Hygiene tasks stack sensory tolerance, executive function sequencing, and transition management at once, and by evening every one of those systems is at minimum capacity. Water temperature, toothpaste texture, standing still, and remembering the steps converge at the worst time, so the refusal is depletion, not defiance. Reduce the steps and make the routine visual. Give them control over the sensory details. The method is negotiable, the teeth get brushed." },
  { id: 'm32', type: 'moment', category: 'sensory', title: 'They asked the same question fifteen times and I snapped', seoTitle: "Why does my child ask the same question over and over?", answerBlock: "Perseverative questioning usually signals one of two ADHD patterns. Either working memory keeps dropping the answer so it never sticks, or anxiety keeps the loop open because the answer never resolved the underlying worry. The repetition is a symptom, not a test of your patience. Answer once more slowly, and if it keeps coming, address the feeling underneath. 'Are you worried about tomorrow?' often closes the loop." },
  { id: 'm33', type: 'moment', category: 'sensory', title: 'The noise and constant talking maxed me out', seoTitle: "Why does my child's constant noise overwhelm me?", answerBlock: "If you have ADHD and sensory sensitivities, you are especially vulnerable to auditory overload, and the narration, sound effects, and volume saturate a system that cannot filter them. Your child's noise is their nervous system's baseline stimulation need, so your need for quiet and their need for output are in direct conflict. Snapping is your capacity filling, not a failure. Name it without blame: 'I need five minutes of quiet.'" },
  { id: 'm34', type: 'moment', category: 'executive-function', title: 'I\'m trying to help with homework but I can\'t focus either', seoTitle: "How do I help with homework when I have ADHD too?", answerBlock: "Helping with homework asks for sustained attention, patience, explanation, and emotional regulation, and every one of those is a prefrontal cortex function running at the same reduced capacity as your child's. Two depleted systems propping each other up is structurally hard. Body-double instead. Sit side by side, each doing your own focused task, so your calm presence provides regulation without demanding executive function you do not have." },
  { id: 'm35', type: 'moment', category: 'emotional', title: 'They\'re convinced everyone hates them after one comment', seoTitle: "Why is my ADHD child sure everyone hates them?", answerBlock: "Rejection sensitive dysphoria activates the same neural circuits as physical pain, so a small or neutral comment gets processed as evidence of fundamental unworthiness. Add the accumulated weight of roughly twenty thousand more negative messages than their peers and it feels enormous. This is neurology, not drama, and explaining why the comment was minor makes it worse. Sit with them and validate: 'That sounds like it really hurt.'" },
  { id: 'm36', type: 'moment', category: 'emotional', title: 'I corrected them gently and they completely shut down', seoTitle: "Why does my ADHD child shut down when I correct them?", answerBlock: "Gentle correction still activates the ADHD rejection sensitivity circuit. The tone barely matters; their brain hears any corrective comment as proof they are fundamentally flawed, so the shutdown is self-protection, not defiance. Give them space now rather than pushing through it. Acknowledge the pain without apologising for the correction, saying something like I can see that was hard to hear. The correction can land tomorrow." },
  { id: 'm37', type: 'moment', category: 'transitions', title: 'Leaving anywhere fun turns into a meltdown', seoTitle: "Why does my ADHD child melt down every time we leave?", answerBlock: "Leaving a preferred activity means disengaging from a dopamine source and dropping toward a less rewarding state, which an ADHD brain registers as genuine neurological loss. The meltdown is withdrawal, not entitlement. Two-minute warnings help a little, but giving them something to move toward helps more. Try telling them that when you reach the car they can choose the music. A next thing makes the loss bearable." },
  { id: 'm38', type: 'moment', category: 'sleep', title: 'They\'re wired at 10pm and physically cannot fall asleep', seoTitle: "Why can't my ADHD child fall asleep even when exhausted?", answerBlock: "ADHD delayed sleep phase releases melatonin later, and in a dark room the default mode network switches on and floods them with racing thoughts. They are not choosing to stay awake; lying there with a racing mind is distressing. Give the brain one channel to track with an audiobook or calm music, and lower the demand from go to sleep to just close your eyes and rest." },
  { id: 'm39', type: 'moment', category: 'honesty', title: 'They lied straight to my face about something small', seoTitle: "Why does my ADHD child lie straight to my face?", answerBlock: "Impulsive lying fires before the honesty-assessment system can intervene. The truth carried a consequence that felt overwhelming, and the prefrontal cortex could not weigh long-term trust against short-term relief in time. The brakes failed; they know lying is wrong. Stay calm and make truth safe by offering a redo, saying I saw what happened, want to try again. A calm response teaches them that honesty is survivable." },
  { id: 'm40', type: 'moment', category: 'impulsivity', title: 'They took something that wasn\'t theirs', seoTitle: "Why does my ADHD child take things that aren't theirs?", answerBlock: "Impulsive taking is usually want-then-take, with no gap for the ethics system to weigh in. The item was wanted, the hand took it, and the should-I question arrived afterwards. This is impulse control failure, not a moral one. Return the item together, calmly and without humiliation, saying we are taking this back because it is not ours. They need to build the pause, not carry shame." },
  { id: 'm41', type: 'moment', category: 'transitions', title: 'Getting out the door for the fun thing fell apart too', seoTitle: "Why can't my ADHD child get ready even for fun outings?", answerBlock: "Anticipation creates a dopamine spike that makes boring preparation steps even harder to start, so their excitement and executive function work against each other. They want to go but cannot do the steps. Their enthusiasm is not fuel, it is interference. Scaffold the logistics without resentment: lay out the clothes, pack the bag, and walk them through each step. Your structure, not their excitement, gets them out the door." },
  { id: 'm42', type: 'moment', category: 'emotional', title: 'They\'re melting down because they\'re overtired but won\'t admit it', seoTitle: "Why does my ADHD child melt down when they're overtired?", answerBlock: "The meltdown is fatigue wearing the mask of emotion. ADHD interoception is unreliable, so tiredness registers as distress rather than sleepiness and they genuinely do not know they are tired. Telling them so feels dismissive because the emotion feels real. Do not argue or name it. Move quietly toward rest without making it the goal, saying let's sit on the couch with a book, and lower the stimulation." },
  { id: 'm43', type: 'moment', category: 'transitions', title: 'We\'re travelling and they\'ve completely unravelled', seoTitle: "Why does my ADHD child fall apart when we travel?", answerBlock: "ADHD brains lean on external structure to make up for internal executive function gaps, and travel strips away every routine, familiar space, and predictable input at once. The dysregulation is proportionate to how much scaffolding was lost. Lower your expectations sharply and rebuild small anchors fast. Keep mealtimes roughly consistent, bring one familiar object from home, and set a short morning routine. It need not be elaborate, only predictable." },
  { id: 'm44', type: 'moment', category: 'siblings', title: 'They won\'t stop touching their sibling and it\'s about to blow', seoTitle: "Why does my ADHD child keep poking their sibling?", answerBlock: "The poking, grabbing, and space-invading is impulsive sensory-seeking, not deliberate provocation. Their nervous system needs proprioceptive input and the sibling is the nearest, most responsive source, so they are not trying to start a fight. Redirect the need before it escalates, while the intervention can still be small. Give them something to squeeze, push, or press against, or physical activity that feeds the input without a victim." },
  { id: 'm45', type: 'moment', category: 'social', title: 'They\'re hyper and loud in public and people are staring', seoTitle: "Why is my ADHD child so loud and hyper in public?", answerBlock: "Hyperactivity is the motor system generating the stimulation an ADHD brain needs to hold its baseline arousal. In a quiet setting that normal speed simply looks like too much, and they are not choosing to be disruptive. The stares land on you, not them, so manage your shame separately. Offer one calm redirect, and if it does not work, leave without drama. Seek environments that match their energy." },
  { id: 'm46', type: 'moment', category: 'medication', title: 'I can\'t tell if this is the meds or just a bad day', seoTitle: "Is my child's behaviour the ADHD meds or just a bad day?", answerBlock: "You may not solve this tonight, because ADHD medication effects interact with sleep, food, stress, and time of day, and isolating one variable from incomplete data is genuinely complex. You are not overthinking a multivariate problem. Quietly note the time, dose, sleep, food, and behaviour, and share them with the prescriber, where patterns emerge over time. Right now, respond to the child in front of you, not the diagnostic puzzle." },

  // ─── NEW PARENT-ONLY CARDS (20) ───
  { id: 'p23', type: 'parent', category: 'medication', title: 'I couldn\'t fill their prescription and tomorrow is an unmedicated day', seoTitle: "I can't fill my child's ADHD prescription for tomorrow.", answerBlock: "A pharmacy shortage is external and beyond your control, so the guilt is misplaced; you did not cause it, and this is a wound the system inflicts, not one you deserve. Write the teacher a brief, factual note tonight with no apology, saying your child will be unmedicated tomorrow due to a supply issue and may need extra support. Then let go of what you cannot control." },
  { id: 'p24', type: 'parent', category: 'medication', title: 'I forgot to reorder the meds in time', seoTitle: "I forgot to reorder my ADHD child's meds in time.", answerBlock: "The refill needed future planning, time awareness, and follow-through, the exact functions your own ADHD impairs, so this is a systems problem, not a character flaw. Do not spiral into self-blame. Call the surgery and the pharmacy now, and if a gap is unavoidable, write the school a short note. Then build a system: a recurring alarm seven days before the script runs out, plus pharmacy auto-refill if it exists." },
  { id: 'p25', type: 'parent', category: 'identity', title: 'I think I have ADHD too and it\'s hitting me hard', seoTitle: "I think I have ADHD too and it's hitting me hard.", answerBlock: "Recognising your own ADHD after your child's diagnosis is one of the most common adult discovery pathways, and the pattern is vivid because you share the neurology. What you are seeing is real. Give yourself time; you do not need to diagnose, disclose, or decide anything tonight. Consider seeking an assessment when you are ready. Understanding your own brain changes how you parent and how you forgive yourself." },
  { id: 'p26', type: 'parent', category: 'identity', title: 'Grieving the childhood I\'d have had if someone had noticed', seoTitle: "Why am I grieving my own undiagnosed ADHD childhood?", answerBlock: "Late-recognised ADHD adults carry a specific grief: years of self-blame for a neurological difference. Every lazy, careless, and not trying hard enough was wrong information about a brain working harder than anyone knew. This is legitimate loss, not self-pity, and naming it is part of processing it. Let yourself sit with it. The grief makes room for self-compassion, and your child will not wait as long as you did." },
  { id: 'p27', type: 'parent', category: 'relationships', title: 'A relative said it\'s just bad parenting', seoTitle: "A relative says my child's ADHD is just bad parenting.", answerBlock: "The comment cut deep because ADHD rejection sensitivity routes it through threat circuits, not simple disagreement, and it landed on the self-doubt you already carry. The pain is neurological, not thin skin. They are not right, but explaining ADHD to someone who rejects it rarely works in the moment. You do not owe them an education tonight. Protect your child, limit the exposure, and process the hurt elsewhere." },
  { id: 'p28', type: 'parent', category: 'relationships', title: 'I defended my kid to a relative and now there\'s tension', seoTitle: "I defended my ADHD child to a relative and it's tense.", answerBlock: "Advocating for your child against family pressure means tolerating disapproval, which is exactly what ADHD rejection sensitivity makes hardest, so the second-guessing is your RSD talking, not your judgement. You drew the boundary despite the pain, and that is strength. Do not retract it. You can soften the delivery later, but the position holds; your child's needs are not negotiable because a relative is uncomfortable." },
  { id: 'p29', type: 'parent', category: 'burnout', title: 'I\'m secretly relieved when they\'re at school and I hate myself for it', seoTitle: "Why do I feel relieved when my ADHD child is at school?", answerBlock: "Chronic caregiver stress drains the same neurological resources ADHD already leaves you short of, so the relief you feel when the demand stops is your nervous system recovering. It is physiological, not optional, and not a sign you love them any less. The guilt is lying about what the relief means. It means you are human, running a harder-than-average version of parenting, and your body knows it." },
  { id: 'p30', type: 'parent', category: 'burnout', title: 'I\'m completely touched out and can\'t be needed for one more second', seoTitle: "Why can't I stand being touched by my kids anymore?", answerBlock: "Being touched out is a real, documented sensory state, not a failure of warmth. ADHD sensory processing can hit overload from sustained physical contact, especially after a day of other sensory demands, so every tug and hug lands on a system with nothing left to receive. This is not rejection of your child. Name it kindly, saying I love you and my body needs five minutes without being touched." },
  { id: 'p31', type: 'parent', category: 'siblings', title: 'I gave my other kid less because this one needed everything', seoTitle: "Am I neglecting my other child because of ADHD needs?", answerBlock: "Attention is a finite resource, and an ADHD child's needs are louder, more urgent, and more visible, so the quieter sibling adapts by going quieter still, dimming their signal that they need you too. You cannot fix the whole pattern tonight, but you can notice it. Give the quiet one ten minutes of undivided attention where they are the only focus, a small deposit in a relationship running on leftovers." },
  { id: 'p32', type: 'parent', category: 'comparison', title: 'I keep comparing them to other kids and hating myself for it', seoTitle: "Why do I keep comparing my ADHD child to other kids?", answerBlock: "Comparison activates the ADHD rejection sensitivity circuit, and the grief that follows is not really about the other child. It is about the gap between the parenting experience you expected and the one you have. Your child is not less than; they are running harder software on the same hardware. The comparison tells you about your own exhaustion, not their worth. Let the shame pass, and close the comparison window." },
  { id: 'p33', type: 'parent', category: 'fear', title: 'I\'m scared about who they\'ll become', seoTitle: "I'm scared about who my ADHD child will become.", answerBlock: "ADHD brains project future scenarios with full emotional intensity, so the catastrophe feels imminent; the emotional system cannot tell the difference between might happen in fifteen years and happening now. This is a rumination spiral, a feeling rather than a prediction. You cannot solve their future tonight. Show up tomorrow instead, because the strongest predictor of outcomes for ADHD children is the parent-child relationship you are actively building." },
  { id: 'p34', type: 'parent', category: 'screen-time', title: 'I let them have too much screen time again because I had nothing left', seoTitle: "I gave my ADHD child too much screen time again.", answerBlock: "Screens deliver predictable, low-demand, high-stimulation input that regulates an ADHD child's nervous system effectively, so you reached for the most reliable tool available when your own regulation was gone. That is resource management under chronic depletion, not a parenting failure. The screen kept them safe and regulated while you recovered enough to keep going, which is harm reduction. Do not stack guilt on top of exhaustion." },
  { id: 'p35', type: 'parent', category: 'burnout', title: 'I\'m exhausted from being the family\'s executive function', seoTitle: "Why am I burnt out being the family's executive function?", answerBlock: "Being the household's executive function while your own is impaired is a structural impossibility most ADHD families face, not a personal weakness, and at this level the load is simply not sustainable. You cannot hold every appointment, form, refill, and routine in a working memory that already drops things. Offload just one thing this week, a shared calendar, an auto-refill, or a standing order. Each system holds one less thing." },
  { id: 'p36', type: 'parent', category: 'school', title: 'I dread every school email and call', seoTitle: "Why do I dread every email and call from the school?", answerBlock: "This is Pavlovian conditioning, not an anxiety disorder. The school's name has been paired with problem reports so often that the association is automatic, and the cortisol spike hits before you open the message. Repeated negative contact trained you to brace for the worst. You are allowed to let the message sit for ten minutes; it will still be there. Read it when you have capacity." },
  { id: 'p37', type: 'parent', category: 'comparison', title: 'I compared my parenting to the calm parent online', seoTitle: "Why does the calm parent online make me feel worse?", answerBlock: "Social media comparison fires the same rejection sensitivity circuits as personal criticism, and the curated calm you are watching is performance, not real parenting. You are holding your own unedited footage up against someone's highlight reel, so of course your reality feels worse. The polished version on the screen does not exist. Close the app. The parent who survived today, imperfectly, snapping and recovering and trying, is the real one." },
  { id: 'p38', type: 'parent', category: 'discipline', title: 'I bribed them just to get through the moment', seoTitle: "Did I teach bad behaviour by bribing my ADHD child?", answerBlock: "Reward-based management is actually an evidence-based ADHD strategy, so what you did works; the guilt comes from calling it bribery rather than an incentive. The only real difference is timing. Bribery responds to escalation, an incentive is planned in advance, but the mechanism is identical. You got through the moment without anyone getting hurt, which counts. Next time, set the reward first: get through this, then earn something good." },
  { id: 'p39', type: 'parent', category: 'isolation', title: 'I\'m lonely and isolated in this', seoTitle: "Why am I so lonely and isolated raising an ADHD child?", answerBlock: "Social withdrawal in burned-out ADHD parents starts as self-protection and quietly becomes self-defeating. Outings feel too unpredictable, so invitations and friendships fall away, but the loss of support only deepens the burnout that made socialising feel impossible. The energy really does feel unavailable, yet the isolation needs a small crack. Aim for one connection this week: text someone who gets it. You need not go anywhere, just reach out." },
  { id: 'p40', type: 'parent', category: 'relationships', title: 'My partner and I parent completely differently and it\'s splitting us', seoTitle: "My partner and I parent our ADHD child so differently.", answerBlock: "Co-parenting an ADHD child is harder because the needs are more complex and the cost of inconsistency is higher, so a structure parent and a flexibility parent leave a gap the child learns to play. This is a structural problem most ADHD families face, not a marriage failing. Shift the question from who is right to what this child needs from both of you as a unit." },
  { id: 'p41', type: 'parent', category: 'burnout', title: 'I\'m resentful of how much harder my life is', seoTitle: "Why do I resent how much harder ADHD makes my life?", answerBlock: "Resentment in chronically stressed caregivers is a documented burnout symptom, not a moral failing. Parenting an ADHD child with your own ADHD brain is measurably heavier than typical parenting, so your feelings are a proportionate response to a disproportionate demand. You can love your child and resent the load at once; both are true, and neither cancels the other. Naming it is the first step to managing it." },
  { id: 'p42', type: 'parent', category: 'school', title: 'I missed an important deadline or form for them', seoTitle: "I missed an important school deadline for my ADHD child.", answerBlock: "The system asked you to remember something important with no external support, and your executive function failed on a task with real consequences, which is painful but predictable. Do not spiral. Contact the school or organisation now and explain, because most deadlines carry more flexibility than they advertise. Then build the system that catches this next time: calendar alerts, phone photos of forms, one landing spot for papers." },

  // ─── NEW KID-ONLY CARDS (5) ───
  { id: 'k12', type: 'kid', category: 'medication', title: 'They won\'t eat on the medication and it scares me', seoTitle: "Why won't my ADHD child eat while on their medication?", answerBlock: "Stimulants raise dopamine and norepinephrine, which suppress the appetite centre in the hypothalamus, so your child genuinely does not feel hungry while the medication is active. This is a side effect, not a food preference, and forcing food now builds a negative association with eating. Load the calories outside the window instead: a big breakfast before the dose kicks in and a protein-dense snack afterwards. Track weight with the prescriber." },
  { id: 'k13', type: 'kid', category: 'sleep', title: 'They can\'t fall asleep no matter what we try', seoTitle: "Why can't my ADHD child fall asleep no matter what?", answerBlock: "ADHD delayed sleep phase is biological: melatonin releases later than in other children, so they are not ready for sleep even when exhausted. In a dark room the default mode network switches on and generates a stream of thoughts that feels impossible to stop. Give the brain one channel to follow with an audiobook or white noise, and lower the demand from sleep to rest. Ask the prescriber about melatonin." },
  { id: 'k14', type: 'kid', category: 'social', title: 'They have no friends and aren\'t getting invited', seoTitle: "Why does my ADHD child struggle to make friends?", answerBlock: "ADHD social processing runs slower, so your child misses subtle cues, misreads timing, interrupts, or reacts too intensely, and each failed interaction feeds rejection sensitivity that makes the next one harder. This is about processing speed, not worth or knowledge, which is why parental instruction helps less than practice. One good friendship matters more than popularity. Choose structured activities with clear rules, and keep telling them they are likeable." },
  { id: 'k15', type: 'kid', category: 'emotional', title: 'They take everything personally and feel rejected constantly', seoTitle: "Why does my ADHD child feel rejected by everything?", answerBlock: "Rejection sensitive dysphoria is a core ADHD feature. Social rejection runs through the same neural circuits as physical pain, so a mild correction or an unanswered text lands with the intensity of public humiliation. The feeling is real and out of proportion at once. Validate first, then gently reality-test. Say that sounds really painful, and only once they are calm, ask what else it could mean." },
  { id: 'k16', type: 'kid', category: 'impulsivity', title: 'They blurt things out and interrupt constantly', seoTitle: "Why does my ADHD child interrupt and blurt things out?", answerBlock: "Verbal impulsivity is one of the most socially costly ADHD symptoms. The thought reaches the speech centre before the inhibition system can catch it, so they know they should wait but the brake fires too slowly. Give them an external one. A raised hand or a token they hold until their turn anchors the pause. Practise in low-stakes moments, and try hold that thought instead of stop interrupting." },

  // ─── 15 NEW KID CARDS ───
  { id: 'k17', type: 'kid', category: 'task-initiation', title: 'They know what to do but they can\'t start', seoTitle: "Why does my child freeze when they know what to do?", answerBlock: "They are not choosing to stand there. Task initiation needs a dopamine signal the ADHD brain cannot produce on demand for non-preferred tasks, so the start button stays disconnected from the knowing. Do not repeat the instruction louder. Walk over, name one tiny physical action, pick up the sock, and start it with them. Your movement is the ignition key their brain is missing." },
  { id: 'k18', type: 'kid', category: 'demand-overwhelm', title: 'Every request feels like an attack to them', seoTitle: "Why does my child treat every request like an attack?", answerBlock: "This is demand overwhelm. When a child is already at capacity, the amygdala reads any new request as a threat and fires no before the content is even evaluated. They did not decide to refuse. Shrink the demand and offer genuine choices. Would you like to start with shoes or jacket gives agency. Declarative language helps too. The shoes go by the door is a statement, not a command." },
  { id: 'k19', type: 'kid', category: 'attention', title: 'They hear me but they don\'t move', seoTitle: "Why does my ADHD child hear me but not move?", answerBlock: "They genuinely heard you. In ADHD, attention can lock onto a preferred task so hard that the release step fails, and switching needs executive function that is not available in the moment. Calling from another room almost never works. Walk over, get close, say their name, and wait for eye contact. Then give one instruction. Physical proximity is the bridge between hearing and doing." },
  { id: 'k20', type: 'kid', category: 'boredom', title: 'They create chaos when they\'re bored', seoTitle: "Why does my child cause chaos when they are bored?", answerBlock: "The chaos is self-made stimulation. The ADHD brain needs more input to reach baseline arousal, and under-stimulation feels physically uncomfortable, so the nervous system generates its own through noise, movement, or conflict. This is a need, not bad behaviour. Meet it through a better channel before the chaos channel takes over. Offer a movement job, a physical challenge, or structured play to feed the brain what it is hunting for." },
  { id: 'k21', type: 'kid', category: 'interoception', title: 'They don\'t notice hunger, tiredness, or needing the toilet until it\'s a crisis', seoTitle: "Why does my child not notice hunger until it is a crisis?", answerBlock: "They genuinely did not feel it coming. ADHD interoception processes body signals on a delayed, muted timeline, so hunger reads as irritability, tiredness as distress, and the toilet need arrives at urgency, not gentle awareness. Do not wait for them to notice, because their body does not reliably tell them. Build external anchors. Schedule snack times, water prompts, and toilet stops at each transition to prevent the crisis." },
  { id: 'k22', type: 'kid', category: 'sequencing', title: 'Multi-step tasks fall apart before they finish', seoTitle: "Why do multi-step tasks fall apart for my ADHD child?", answerBlock: "They did not give up. Multi-step tasks mean holding the whole plan in working memory while running each step, and ADHD working memory is smaller, so by step three the map has dropped out. Move the plan out of their head. Put a visual checklist at the point of action, each step written, showing what done looks like. Do the first step together. The list is the system." },
  { id: 'k23', type: 'kid', category: 'shame', title: 'They say they\'re stupid or bad', seoTitle: "Why does my child say they are stupid or bad?", answerBlock: "They are telling you what they believe. By age twelve a child with ADHD has received roughly twenty thousand more corrective messages than peers, and each one aimed at character rather than behaviour builds a self-concept of being broken. Do not dismiss it or over-reassure. Separate behaviour from identity and name specific, recent strengths. You were really patient with that puzzle builds a counter-narrative one data point at a time." },
  { id: 'k24', type: 'kid', category: 'frustration', title: 'They give up the second something gets hard', seoTitle: "Why does my child give up the second something gets hard?", answerBlock: "The difficulty triggered escape before problem-solving could start. Effort is neurologically expensive for the ADHD brain, so the cost of trying is felt immediately while the reward of success stays abstract and delayed, and the system chooses escape. This is not laziness. Lower the bar to a height they can clear, just do the first line, then raise it gradually. Praise the attempt, not the result. Starting is the skill." },
  { id: 'k25', type: 'kid', category: 'anxiety', title: 'They need constant reassurance and it never seems enough', seoTitle: "Why is reassurance never enough for my anxious child?", answerBlock: "The answer never sticks because it treats the question, not the anxiety underneath. Anxiety frequently co-occurs with ADHD, and repeated executive function failures build a general expectation that things will go wrong, so reassurance leaves the pattern untouched. Reduce uncertainty with visual schedules and written plans. Then reach the root. Say the worry seems bigger than the question, and ask what they are worried about underneath." },
  { id: 'k26', type: 'kid', category: 'emotional', title: 'They calm down and then feel awful about what they did', seoTitle: "Why does my child feel awful after they calm down?", answerBlock: "This is the emotional hangover. The ADHD sequence is feel, act, think. The emotion arrives at full intensity and drives the action before the reflective brain can moderate it, then awareness of the impact lands afterward carrying its own shame. Do not add a lecture; they already know. Say that was hard, we can fix this, then show them the repair. The repair teaches mistakes are survivable and relationships recover." },
  { id: 'k27', type: 'kid', category: 'transitions', title: 'They can\'t stop one thing and start the next', seoTitle: "Why can't my child stop one thing and start the next?", answerBlock: "Every transition is four executive function steps in sequence: disengage, shift attention, plan the next action, and initiate. Each runs on the prefrontal cortex, the exact region ADHD impairs, and the more depleted the child, the more steps fail. Build a bridge across the gap. A countdown gives time to disengage, a named next activity gives something to move toward, and a physical cue supplies the start signal." },
  { id: 'k28', type: 'kid', category: 'sensory', title: 'Busy places are too much and they shut down or explode', seoTitle: "Why do busy places make my ADHD child shut down?", answerBlock: "Their sensory gating is less efficient, so inputs other children background-process arrive at full conscious awareness. A busy shopping centre or party produces hundreds of signals a minute with no dimmer, and the system overloads into shutdown or explosion. This is overload, not defiance. Reduce the input or leave. Headphones, sunglasses, a quiet corner, or an early exit all work. Forcing them to tolerate it builds aversion, not resilience." },
  { id: 'k29', type: 'kid', category: 'siblings', title: 'They keep provoking their sibling even though they know it ends badly', seoTitle: "Why does my child keep provoking their sibling?", answerBlock: "The provocation is usually stimulation-seeking, not cruelty. A sibling delivers unpredictable reactions, physical input, and emotional intensity, all neurologically stimulating, and the impulse to chase that input fires before the consequence can be weighed. Redirect the need rather than punishing the child. Offer rough-and-tumble play, something to squeeze, or physical activity with no victim. Separate them early, before the escalation. The need is valid. The target has to change." },
  { id: 'k30', type: 'kid', category: 'movement', title: 'Their body is always moving and they can\'t make it stop', seoTitle: "Why can't my child sit still and stop moving?", answerBlock: "Movement is regulation, not misbehaviour. The ADHD motor system is under-stimulated at baseline, and bouncing, tapping, or climbing generates the proprioceptive and vestibular input that lifts arousal to a functional level. Sitting still drains the energy they need to think, so they focus less when forced to freeze. Accommodate the movement rather than suppressing it. A wobble cushion, standing option, or fidget tool lets them regulate. Stillness is the mismatch." },
  { id: 'k31', type: 'kid', category: 'sleep', title: 'Bedtime makes them more awake, not less', seoTitle: "Why does bedtime make my ADHD child more awake?", answerBlock: "Their brain winds up when the world goes quiet. ADHD carries a delayed sleep phase, so melatonin releases later, and the default mode network switches on without external input, generating racing thoughts. A dark, silent room is the worst environment for this. Give the brain one channel to follow, an audiobook or white noise, and drop the demand from sleep to listen and rest. Ask the prescriber about melatonin timing." },

  // ─── 9 NEW PARENT CARDS ───
  { id: 'p43', type: 'parent', category: 'demand-stacking', title: 'I lost it over something tiny because the whole day had stacked up', seoTitle: "Why do I snap over something tiny at the end of the day?", answerBlock: "The tiny thing was not the trigger, only the last input in a day of invisible demands. ADHD executive load accumulates with no visible meter, so each demand felt manageable while the cost built until the final item tipped the system. My snap was sized for the pile, not the item. Ask what else is in the pile. Write three things down, then reduce the next demand, not the child." },
  { id: 'p44', type: 'parent', category: 'control', title: 'I became so controlling that I made everything worse', seoTitle: "Why does controlling everything make my mornings worse?", answerBlock: "I tightened because the uncertainty felt intolerable. Control is a common ADHD coping strategy. When executive function cannot reliably plan or remember, controlling the environment substitutes for controlling the brain, and the need grows as I get depleted. But micromanaging removes my child's agency and feeds their demand-avoidance, creating new chaos. Choose one non-negotiable today and let the rest be good enough. The relationship is what I am protecting." },
  { id: 'p45', type: 'parent', category: 'repair', title: 'I know I should apologise but I can\'t make myself do it', seoTitle: "Why can't I make myself apologise to my child?", answerBlock: "The avoidance is shame, not indifference. Repair requires emotional regulation right after a rupture, the exact function that just failed, and the shame of snapping activates the same avoidance circuits that drive procrastination, so the apology feels impossible. Keep it small. Twenty seconds, two sentences. I snapped, that was too much, I am sorry. Then return to normal. The return to normal is the repair, showing relationships survive rupture." },
  { id: 'p46', type: 'parent', category: 'clutter', title: 'The house is out of control and I can see the mess but can\'t start', seoTitle: "Why can't I start cleaning when I can see the mess?", answerBlock: "I can see every item, but fixing it means deciding what to pick up, where it goes, in what order, and what counts as done, and each decision costs executive function I do not have. ADHD object permanence means things out of place stop being tracked until the mess registers all at once. Do not tackle the room. Pick one surface, set a five-minute timer, and stop when it goes." },
  { id: 'p47', type: 'parent', category: 'accommodation', title: 'Am I helping my child or letting them get away with it', seoTitle: "Am I helping my ADHD child or letting them off?", answerBlock: "Usually you are helping. ADHD brains genuinely need external scaffolding, which the culture wrongly frames as excuses. The framework is scaffold-and-fade: provide support now and reduce it gradually as the skill develops, so direction matters more than amount. Ask whether this accommodation builds capacity over time or permanently avoids the demand. A visual checklist builds independence. Doing everything for them does not. Sometimes doing it today is right." },
  { id: 'p48', type: 'parent', category: 'stimulation', title: 'I created chaos when things were finally calm', seoTitle: "Why do I create chaos when things are finally calm?", answerBlock: "The calm felt uncomfortable because my ADHD nervous system reads low stimulation as boredom, which is physically unpleasant, so it self-medicates through novelty and intensity. That is why I start a project, rearrange furniture, or pick a fight the moment things settle. Catch the urge before acting on it. When my body starts scanning for input, add safe stimulation instead. Music, a walk, a fidget. Do not detonate the routine." },
  { id: 'p49', type: 'parent', category: 'contagion', title: 'I caught my child\'s mood and matched their anger instead of calming them', seoTitle: "Why do I match my child's anger instead of calming them?", answerBlock: "Their anger entered my nervous system through limbic resonance before my prefrontal cortex could intervene. Mirror neurons copied their tone, and my amygdala read their alarm as my own. In ADHD parents this contagion is faster and less filtered because the prefrontal moderator is less reliable. I did not choose to match them. Co-regulation needs one person regulated first, so lower your volume and slow down. Your system leads theirs." },
  { id: 'p50', type: 'parent', category: 'perfectionism', title: 'I built a perfect system and abandoned it after three days', seoTitle: "Why do I abandon every routine after a few days?", answerBlock: "The system was too big. ADHD perfectionism is protective. If the routine is perfect it will compensate for the imperfect brain, but perfect systems need perfect maintenance, which requires the exact executive function the system was meant to replace, so the collapse is structural, not motivational. Shrink it. Keep the one part that worked today. A three-item checklist that survives the week beats a colour-coded planner that dies on Wednesday." },
  { id: 'p51', type: 'parent', category: 'decision-fatigue', title: 'I can\'t make basic parenting decisions anymore', seoTitle: "Why can't I make basic parenting decisions by evening?", answerBlock: "By evening the decision-making system is empty. Decision fatigue is real, and ADHD amplifies it. Every choice draws on prefrontal cortex resources, and after hundreds of parenting micro-decisions there is nothing left to weigh options, so dinner feels as heavy as a boundary. Pre-decide the recurring choices. Monday is pasta, the screen consequence never changes, bedtime order stays fixed. Each default removes one decision. Defaults are infrastructure, not rigidity." },

  // ─── 25 MORE CARDS ───
  { id: 'm47', type: 'moment', category: 'emotional', title: 'They screamed I hate you and slammed the door', seoTitle: "What do I do when my child screams they hate me?", answerBlock: "They aimed for maximum impact because their pain was at maximum. Under emotional flooding, verbal impulsivity turns the most devastating thought into speech before any filter can intervene, so the words are the feeling, not the truth. Do not respond to the content, defend yourself, or follow them. Let them have the room. Give ten minutes, then a quiet knock. I am here when you are ready." },
  { id: 'm48', type: 'moment', category: 'social', title: 'The playdate went wrong and the other parent saw everything', seoTitle: "What do I do when another parent sees the meltdown?", answerBlock: "You are carrying two loads at once, your child's dysregulation and your own rejection sensitivity reading the other parent's face as proof you are failing. That perceived judgment fires pain circuits alongside the parenting stress. Their opinion is not data about your parenting. Deal with your child first and move them away from the observer, because your attention signals safety. A brief they are having a tough day is plenty." },
  { id: 'm49', type: 'moment', category: 'transitions', title: 'The birthday party was too much and they fell apart', seoTitle: "Why does my child fall apart at birthday parties?", answerBlock: "Parties stack every ADHD trigger at once: sensory overload, unstructured time, social processing, constant transitions, and sugar. The anticipated joy creates a dopamine spike that raises arousal before it starts, then the overload pushes it past threshold, and the crash is the gap between expected and actual feeling. This is capacity exceeded, not ingratitude. Take a quiet five-minute break to reset, and if that is not enough, leave without shame." },
  { id: 'm50', type: 'moment', category: 'medication', title: 'They refused to take their medication this morning', seoTitle: "What do I do when my child refuses their medication?", answerBlock: "Refusal can signal side effects they cannot articulate, control-seeking in a life where little feels controllable, or a morning executive function failure that makes swallowing a pill feel enormous. Force does not work and damages the medication relationship long-term. Offer a choice of method, not whether. With juice or with yoghurt. If it persists, note it, tell the teacher, and raise it with the prescriber. One unmedicated day is manageable." },
  { id: 'm51', type: 'moment', category: 'emotional', title: 'They destroyed something in anger and now everyone is in shock', seoTitle: "What do I do when my child breaks something in anger?", answerBlock: "The destruction was not planned. An impulse to discharge overwhelming emotion reached the motor system and found the nearest breakable object faster than any consequence assessment could fire. They may be horrified. Secure safety first, then stay silent. Do not itemise the damage aloud; the shame inside them is already doing that accounting. Say that was a big feeling, are you okay. The property conversation waits until both are calm." },
  { id: 'm52', type: 'moment', category: 'emotional', title: 'They exploded because I said no', seoTitle: "Why does my child explode every time I say no?", answerBlock: "ADHD emotional regulation has no dimmer on disappointment, so no arrives at the same neural intensity as a genuine loss, and processes a denied want as a denied need. The rage matches how it was experienced, not what was refused. Hold the boundary, because caving teaches that enough intensity overrides decisions. Validate while you hold the limit. I can see you wanted that, and the answer is still no." },
  { id: 'm53', type: 'moment', category: 'school', title: 'The school called again and I am dreading the conversation', seoTitle: "Why do I dread every phone call from the school?", answerBlock: "Your cortisol spikes before you hear a word because of Pavlovian conditioning. School contact has been paired with negative reports enough times that the dread is automatic, and ADHD rejection sensitivity amplifies every concern into a judgment of your parenting. Take one breath, then keep it concrete. Ask what exactly happened and what you need from me. You are not obligated to solve it on the call." },
  { id: 'm54', type: 'moment', category: 'emotional', title: 'They are spiralling about something unfair and cannot let it go', seoTitle: "Why can't my child let go of something that felt unfair?", answerBlock: "ADHD justice sensitivity fires pain circuits when fairness is violated, and the loop persists because the resolution the brain wants cannot come from logical argument. They may know it is not a big deal. The feeling disagrees. Arguing that it was fair will not work; the emotional processing must happen before the cognitive can begin. Validate first. Say I can see that feels really unfair. Then ask what would help." },
  { id: 'm55', type: 'moment', category: 'emotional', title: 'They came home from school and emotionally dumped everything on me', seoTitle: "Why does my child fall apart the moment they get home?", answerBlock: "After-school dumping is decompression. Your child held it together all day by masking, which burns enormous regulatory resources, and now the mask drops onto the safest person in their world. The distress is discharging, not accusing you. Skip the fixing and the call to school. Sit close, offer a snack, and say that sounds like a really hard day. Fifteen minutes of being heard settles them faster than any solution." },
  { id: 'm56', type: 'moment', category: 'medical', title: 'The waiting room meltdown at the doctor or dentist', seoTitle: "How do I stop a waiting room meltdown at the doctor?", answerBlock: "A waiting room stacks fluorescent lights, unfamiliar people, unstructured time, and dread of what is coming, and an ADHD nervous system has no mechanism for patient waiting in that mix. The meltdown is overload, not misbehaviour. Prepare instead of hoping. Bring a fidget, headphones, and something for their hands, tell them exactly what will happen, and ask the front desk about sensory-friendly times or waiting outside." },
  { id: 'p52', type: 'parent', category: 'school', title: 'The IEP or accommodation meeting left me feeling dismissed', seoTitle: "Why did my child's IEP meeting leave me feeling dismissed?", answerBlock: "Advocating inside an institution demands sustained focus, emotional regulation under pressure, and tolerance of perceived criticism, and ADHD makes each harder, so the meeting drains exactly what you needed walking in. Feeling dismissed is valid, not oversensitive. Move the fight onto paper. Document what was discussed, follow up by email, and request each accommodation in specific written language. The paper trail carries more weight than the room did." },
  { id: 'p53', type: 'parent', category: 'identity', title: 'Both of us have ADHD and the house is in freefall', seoTitle: "Why does our house fall apart when both of us have ADHD?", answerBlock: "In a dual-ADHD home there is no neurotypical anchor to catch what falls, so working memory failures multiply and dysregulation synchronises. The chaos is structural, not a sign of a bad relationship or bad parenting. Stop trying to run a neurotypical house. Externalise everything onto a shared calendar, whiteboard, and automated reminders, then pick the one system that matters most this week and let the rest stay imperfect." },
  { id: 'p54', type: 'parent', category: 'fear', title: 'I found out they have been bullied and I do not know what to do', seoTitle: "What do I do now I know my child is being bullied?", answerBlock: "The discovery fires a primal protective response, and your own history of rejection amplifies the pain because you know how exclusion feels. That overlap can push you to act for yourself rather than for them, so separate the two first. Ask your child what they need before deciding anything, then contact the school calmly and specifically. Regulated, fierce advocacy teaches them problems get solved without panic." },
  { id: 'p55', type: 'parent', category: 'shame', title: 'The school told me my child bullied someone', seoTitle: "What do I do when the school says my child is bullying?", answerBlock: "ADHD impulsivity means the cruelty was likely more reactive than planned, and that changes the fix, since impulse-driven hurt responds to skill-building while calculated hurt responds to consequences. The shame is real but it is not a verdict on your child. Get the specific facts, then talk to your child without horror on your face. Address the behaviour, repair with the other family, and find the missing skill." },
  { id: 'p56', type: 'parent', category: 'grief', title: 'Report card day and I am bracing for the worst', seoTitle: "Why do I dread my ADHD child's report card so much?", answerBlock: "A report card measures the gap between what school expects and what an ADHD brain delivers. It never captures effort, which stays invisible and enormous, and reading grades as a verdict on your parenting is rejection sensitivity, not fact. Read it once, then put it away. Keep only the specific data, which subjects and skills and contexts, to guide support. The grades describe environment fit, not worth." },
  { id: 'p57', type: 'parent', category: 'identity', title: 'Someone questioned whether my child really has ADHD', seoTitle: "How do I respond when people doubt my child's ADHD?", answerBlock: "A comment like they seem fine to me lands on rejection sensitivity and reopens every doubt you have carried, but that pain is neurological, not evidence. The diagnosis came from a professional with training, assessment tools, and clinical judgement a casual observer lacks. You owe no one a defence. We are working with professionals on this is a complete answer. Save the full picture for your child's care team." },
  { id: 'p58', type: 'parent', category: 'fear', title: 'I think there is something else going on underneath the ADHD', seoTitle: "What if more is going on than just my child's ADHD?", answerBlock: "ADHD frequently travels with anxiety, depression, autism, and learning disabilities, so noticing that the ADHD explanation does not cover everything is pattern recognition, not catastrophising. Your instinct is data, and parents who raise the question early get better outcomes. Trust it. Talk to the prescriber or request a broader assessment, and name the behaviours that do not fit, the deeper anxiety, low mood, or rigidity you keep seeing." },
  { id: 'k32', type: 'kid', category: 'identity', title: 'They asked why they are different from other kids', seoTitle: "How do I answer when my child asks why they are different?", answerBlock: "By school age most ADHD children already sense the difference, so the question is about identity, not information, and your answer shapes how they see themselves. Be honest without being clinical. Tell them their brain works differently, making some things harder and some easier, then name one real hard thing and one real strength. Skip the superpower and disorder framing. Keep it to a sentence they can revisit." },
  { id: 'k33', type: 'kid', category: 'emotional', title: 'They fixate on what is unfair and cannot move past it', seoTitle: "Why does my ADHD child fixate on what is unfair?", answerBlock: "ADHD justice sensitivity turns unfairness into a pain-level response, and the feeling stays stuck in a loop because it has not been discharged. Logic will not release it; only validation does. So validate the feeling before the interpretation. Say that feels really unfair and mean it, then let it land before explaining anything. The acknowledgement is the exit. Once the feeling is seen, your reasoning can finally get through." },
  { id: 'k34', type: 'kid', category: 'anxiety', title: 'They are anxious about tomorrow and cannot switch it off', seoTitle: "Why can't my child stop worrying about tomorrow?", answerBlock: "An ADHD brain cannot separate imagining a future event from living it, so anticipatory anxiety fires the same stress circuits the real event would, and tomorrow's worry becomes today's suffering. Telling them it will be fine fails, because their brain shows evidence it will not. Make the unknown known instead. Write down what will actually happen, show them the plan, and promise you will handle it together." },
  { id: 'k35', type: 'kid', category: 'boredom', title: 'They keep saying they are bored and expecting me to fix it', seoTitle: "Why does my ADHD child say they are bored constantly?", answerBlock: "ADHD baseline arousal runs lower than neurotypical, so when stimulation drops below threshold the discomfort drives stimulation-seeking, and I am bored is really a request for input their brain cannot generate alone. It is not laziness or lack of imagination. Do not recite twenty ideas. Offer two choices, or better, a physical task, a movement challenge, a building project, or a timed race. Boredom lifts when stimulation meets the threshold." },
  { id: 'k36', type: 'kid', category: 'impulsivity', title: 'They were rough with the pet and did not mean to hurt it', seoTitle: "Why is my ADHD child so often too rough with our pet?", answerBlock: "Proprioceptive calibration in ADHD can be unreliable, so force that feels moderate to your child is actually excessive, and the impulse to touch arrives before any judgement of how hard. This is a calibration problem, not malice. Handle the pet's safety first, then teach the skill physically, not verbally. Guide their hand, show the pressure difference, name too much versus right, and supervise practice until gentle holds." },
  { id: 'k37', type: 'kid', category: 'honesty', title: 'They said they have no homework when they do', seoTitle: "Why does my child lie about having no homework?", answerBlock: "Homework-avoidance lying is the ADHD brain trading long-term consequence for short-term relief, because the executive function cost of starting feels enormous and the lie removes the demand instantly. It is avoidance, not deception. Do not make the lie bigger than the homework. Say you know it feels hard, that lying makes tomorrow harder, and offer ten minutes together now. Make asking for help feel safer than lying." },
  { id: 'k38', type: 'kid', category: 'emotional', title: 'They copy bad behaviour from other kids then cannot stop', seoTitle: "Why does my child copy other kids' bad behaviour?", answerBlock: "Copied behaviour sticks when it earns a reaction, and ADHD brains are especially drawn to novel, high-stimulation social feedback, so the audience keeps it alive, not your child's values. Forbidding it only adds appeal. Take the reward away instead. Keep your face and voice flat, redirect without a big discussion, and say that works differently in our house. The less attention it pulls, the faster it fades." },
  { id: 'k39', type: 'kid', category: 'chores', title: 'They will not do any chores or responsibilities without a fight', seoTitle: "Why is every chore a fight with my ADHD child?", answerBlock: "Non-preferred tasks carry the highest executive function cost and the lowest dopamine return, and every chore step demands initiation, attention, and working memory, all depleted by evening, so the fight itself burns more than the chore would. Stop arguing about whether they should do it. Make it smaller and visual instead. Put a checklist on the wall showing one step at a time, and acknowledge each finish immediately." },

  // ─── 50 NEW CARDS ───
  { id: 'k40', type: 'kid', category: 'discipline', title: 'Consequences do not work and I do not know what else to do', seoTitle: "Why don't consequences work on my ADHD child?", answerBlock: "ADHD brains discount future consequences far more steeply than neurotypical brains, so a punishment arriving an hour later is neurologically disconnected from the behaviour; the bridge is too long for working memory to hold. It failed because it relies on a function they cannot reliably access, not because they do not care. Switch to natural consequences that land immediately, collaborative problem-solving, and reducing the demand that triggered it." },
  { id: 'k41', type: 'kid', category: 'discipline', title: 'Rewards do not work either and now I feel out of options', seoTitle: "Why do reward charts stop working after a few days?", answerBlock: "Reward charts run on sustained motivation toward a delayed payoff, but the ADHD interest-based nervous system runs on novelty, urgency, and interest, so once the chart stops feeling new the fuel is gone. Your child is not being manipulative; the dopamine source expired. Match the system to the brain instead. Rotate rewards often, keep them small, and deliver immediately, because a reward earned today beats ten promised next week." },
  { id: 'k42', type: 'kid', category: 'discipline', title: 'They say sorry and then do the same thing again', seoTitle: "Why does my child apologise then do it all again?", answerBlock: "The apology and the repeat come from two different brain systems. The reflective one that produced the sorry is slower and weaker than the impulsive one that produced the behaviour, so your child meant the apology and still could not stop the impulse. The remorse is real, and eroding trust misreads it. Stop asking whether they are sorry and ask which skill is missing, then build that skill." },
  { id: 'k43', type: 'kid', category: 'discipline', title: 'They know the rule but still cannot follow it in the moment', seoTitle: "Why can't my child follow a rule they clearly know?", answerBlock: "Knowing a rule and following it under pressure are different functions. Rule knowledge sits in declarative memory, but following it in the moment needs executive function, inhibition, working memory, and self-monitoring at once, and ADHD impairs the doing, not the knowing. The amygdala also fires faster than the prefrontal cortex. Move the rule out of their head and into the environment, a sign or visual cue where the action happens." },
  { id: 'm57', type: 'moment', category: 'discipline', title: 'Every consequence turns into an argument or explosion', seoTitle: "Why does every consequence turn into a huge argument?", answerBlock: "ADHD emotional reactivity can make a consequence register like a genuine threat, so the loss triggers a meltdown that swallows the original behaviour. Your child is not being dramatic; their nervous system processed it more intensely than you intended. Scale the consequence down. One that sparks a long meltdown teaches nothing and drains regulation you both need. Revisit the behaviour once everyone is calm." },
  { id: 'p59', type: 'parent', category: 'discipline', title: 'I cannot tell if I am being too soft or too harsh', seoTitle: "How do I tell if I am being too soft or too harsh?", answerBlock: "ADHD parenting runs on hundreds of micro-decisions a day about where to hold firm and where to flex, each drawing on executive function, and there is no reliable formula, so what works Monday fails Wednesday. You are not too soft or too harsh; you are deciding with imperfect information and a depleted brain. The middle ground moves. When you cannot tell, pick the option that protects the relationship today." },
  { id: 'p60', type: 'parent', category: 'discipline', title: 'People keep telling me to be firmer and I want to scream', seoTitle: "Why does being told to be firmer make me want to scream?", answerBlock: "Firmness only works when a child can process a boundary, but an ADHD brain under stress processes threat instead, so pushing harder escalates it further. The advice stings because it hits your rejection sensitivity and cannot see the invisible context, the medication timing and sensory profile behind it. You are not failing to be firm; you are choosing not to escalate. We are working with professionals is enough." },
  { id: 'm58', type: 'moment', category: 'discipline', title: 'Taking things away just makes them angrier', seoTitle: "Why does taking things away make my child angrier?", answerBlock: "Loss aversion runs amplified in ADHD, so a removed item occupies working memory at the expense of the lesson, and your child mourns the loss rather than learning. The anger is the emotional response consuming all available processing. Flip the structure. Add contingent access instead of removing it, so you can have screen time after homework works far better than no screen time because you skipped it." },
  { id: 'k44', type: 'kid', category: 'hygiene', title: 'They waited too long to go to the toilet and now everything is a crisis', seoTitle: "Why does my child wait too long to go to the toilet?", answerBlock: "ADHD interoception processes internal signals on a delay, so the bladder cue arrives at crisis intensity instead of gentle awareness, and the accident or near-miss is late signalling, not laziness or defiance. Their body does not warn them in time, so stop waiting for them to notice. Build external prompts instead, with toilet stops at every transition, before leaving, and after meals. Schedule the check-in their body cannot provide." },
  { id: 'k45', type: 'kid', category: 'hygiene', title: 'I found hidden dirty underwear and I do not know how to react', seoTitle: "Why does my child hide their dirty underwear?", answerBlock: "The hiding is shame avoidance, not deception. For an ADHD child the shame of the accident outweighs the risk of being caught, so hiding becomes the path of least immediate cost while long-term consequences get discounted. React with less than they expect. Say you found these, into the wash, no big deal, and keep your face calm. Your reaction now decides whether they hide or tell you next time." },
  { id: 'k46', type: 'kid', category: 'hygiene', title: 'They will not wipe properly and I am trying not to shame them', seoTitle: "Why won't my child wipe properly after the toilet?", answerBlock: "Wiping is a multi-step motor sequence that needs body awareness, motor planning, and sensory tolerance, all of which ADHD and sensory processing differences can impair, so it is genuinely harder for your child, not lazier. Skip the shame and solve the mechanics. Wet wipes are easier to control than dry paper, and a bidet attachment removes the demand entirely. Teach the specific technique matter-of-factly rather than repeating the instruction." },
  { id: 'p61', type: 'parent', category: 'hygiene', title: 'I am so tired of poop', seoTitle: "Why is ADHD hygiene such an exhausting daily battle?", answerBlock: "ADHD hygiene struggles stack interoception delays, sensory aversion to wiping, executive function gaps, and shame avoidance, and it lands on you as manager of a problem that should have ended years ago. That should is what exhausts you. This is a legitimate challenge, not your failure. Cut the load with practical systems, bidet attachments, scheduled toilet times, wet wipes, matter-of-fact language. Systems help; shame does not." },
  { id: 'k47', type: 'kid', category: 'hygiene', title: 'They smell bad but will not shower or use deodorant', seoTitle: "Why won't my child shower even though they smell?", answerBlock: "Olfactory habituation means your child genuinely cannot smell their own scent, and the shower demands task initiation plus sensory tolerance of water and a multi-step sequence, all of which ADHD impairs, so the resistance is avoidance of real discomfort. Lower the threshold rather than forcing the full routine. Offer three minutes, no hair wash, and their choice of products. Build the habit first, then add steps once it holds." },
  { id: 'k48', type: 'kid', category: 'hygiene', title: 'Puberty has started and hygiene is suddenly a daily fight', seoTitle: "Why has puberty made my child's hygiene a daily fight?", answerBlock: "Puberty piles new hygiene tasks, deodorant, daily showering, changing underwear, managing body hair, onto an executive function system already at capacity, and each is another sequence to start, remember, and sustain while hormones, identity, and social pressure draw on the same resources. Treat it as skill-building, not character correction. Put written checklists in the bathroom, let them choose their own products, and keep every conversation free of shame." },
  { id: 'k49', type: 'kid', category: 'hygiene', title: 'They are old enough to do basic hygiene but still need me', seoTitle: "Why does my child still need reminding for basic hygiene?", answerBlock: "ADHD delays executive function development by roughly 30 percent, so a twelve-year-old may run on the executive function of an eight-year-old, which means your reminding is not enabling, it is matching support to where they actually are. Removing it creates failure, not independence. Shift the cue from your voice to the environment instead, using visual checklists, phone alarms, and a laminated card on the mirror. The prompt moves outside you." },
  { id: 'p62', type: 'parent', category: 'resentment', title: 'I resent my child and I hate that I feel that', seoTitle: "Why do I resent my child and feel so guilty about it?", answerBlock: "Resentment is not a failure of love; it is a depletion signal from a nervous system under unrelenting demand for too long. You resent the situation, not the child, even though it feels aimed at them. Hidden, it compounds; named, it can be addressed. Name it to a therapist or someone you trust, and treat it as a cue to reduce load and find support. You are exhausted, not bad." },
  { id: 'p63', type: 'parent', category: 'resentment', title: 'I do not like being around my child right now', seoTitle: "Why do I not enjoy being around my child right now?", answerBlock: "Sustained exposure to high-intensity emotional output depletes your regulatory capacity, so the urge to avoid is protective, not selfish, and loving your child while not wanting to be in the room are both true at once. The guilt does not change the biology. Find one real moment of connection today, not a manufactured performance, just five minutes of a shared interest. The relationship repairs in micro-moments, not grand gestures." },
  { id: 'p64', type: 'parent', category: 'hypervigilance', title: 'I am always waiting for the next explosion', seoTitle: "Why do I feel on edge waiting for the next meltdown?", answerBlock: "When you feel permanently on edge, your nervous system is stuck in threat-scan mode. This is hypervigilance, a response to unpredictable emotional intensity, and your body has learned that calm precedes chaos. Chronic cortisol is exhausting you. Name it, and treat it as real. Trauma-informed therapy can help recalibrate a threat-detection system running on a setting meant for emergencies, not daily life." },
  { id: 'p65', type: 'parent', category: 'fear', title: 'I am scared of my child during violent outbursts', seoTitle: "Is it normal to be scared of my child during meltdowns?", answerBlock: "Yes. A child in a violent meltdown activates your threat-detection system, and that fear is proportionate to the physical reality, whatever your child intends. Being frightened is not failing. Prioritise physical safety, yours and theirs, in the moment. If the outbursts are escalating, get professional support to build a de-escalation and safety plan. No one should have to handle this alone." },
  { id: 'p66', type: 'parent', category: 'hurt', title: 'They hurt me during a meltdown and I cannot just move on', seoTitle: "My child hurt me in a meltdown and I cannot move past it", answerBlock: "Both things are true: it was the ADHD, and it hurt you. Your body processes physical impact as threat regardless of the explanation, so understanding the neurology does not switch off the stress response. You are allowed time to recover. You can say 'that hurt me and it is not okay' without being punitive. Physical safety is non-negotiable for everyone, including you." },
  { id: 'p67', type: 'parent', category: 'rumination', title: 'They said something cruel and I cannot stop replaying it', seoTitle: "Why can't I stop replaying the cruel thing my child said?", answerBlock: "The words loop because ADHD rumination locks onto emotionally charged content, and rejection sensitivity amplifies each replay instead of resolving it. The charge has not been discharged. Interrupt it on paper. Write down exactly what your child said, then write what you know to be true about your relationship. A written counter-narrative breaks the loop the internal one cannot. The words were the emotion, not the truth." },
  { id: 'p68', type: 'parent', category: 'burnout', title: 'I feel numb instead of loving', seoTitle: "Why do I feel numb toward my child instead of loving?", answerBlock: "The numbness is not indifference. After cycling through anger, guilt and shame too many times, your feeling system switches to conservation mode and goes offline. This is burnout, an emotional shutdown under sustained overload. The love is still there underneath it and usually returns as the pressure drops. Focus on reducing the load, and if the numbness stays, explore it with a professional. It is a signal, not a flaw." },
  { id: 'p69', type: 'parent', category: 'emotional', title: 'One bad morning from them ruins my whole day', seoTitle: "Why does one bad morning with my child ruin my whole day?", answerBlock: "An ADHD brain cannot compartmentalise the way a neurotypical one can. Because the morning event was interrupted rather than fully processed, the emotional residue stays active in working memory, using up space you need for the rest of the day. Name it out loud: 'I am still carrying this morning.' Then do one physical reset, a walk or a shower, to signal your brain the context has changed." },
  { id: 'p70', type: 'parent', category: 'burnout', title: 'I am sick of being told to look after myself when I have nothing left', seoTitle: "Why does self-care advice feel impossible when I'm this depleted?", answerBlock: "Because self-care advice assumes you have executive function, time, and someone to hold the load while you step away, and right now you may have none of those. The advice is not wrong, it is inaccessible. What you need is load reduction, not a bubble bath. Cancel something, lower a standard, remove one demand from tomorrow. That is worth more than an hour of meditation you cannot reach." },
  { id: 'p71', type: 'parent', category: 'siblings', title: 'My other child is getting the leftovers of me', seoTitle: "How do I make sure my other child feels seen too?", answerBlock: "Your quieter child is learning that the loudest need gets the attention, and may be suppressing their own needs to avoid adding to the load. That is its own harm. Say something specific: 'I noticed you waited while I dealt with that. That was mature, and I appreciate it.' Then give them five minutes of undivided attention. Not a speech, just proof you see them. They are counting." },
  { id: 'm59', type: 'moment', category: 'siblings', title: 'My other child is starting to hate their ADHD sibling', seoTitle: "What do I do when my child resents their ADHD sibling?", answerBlock: "Living with a high-intensity sibling depletes your other child's emotional resources, so their resentment is proportionate to their experience. Validate it without betraying either child: 'I know it is hard when things get loud. Your feelings about that are fair.' Then protect their space with a locked door, headphones, or a sibling-free zone. Their need for peace is as valid as their sibling's need for support." },
  { id: 'm60', type: 'moment', category: 'siblings', title: 'They ruined their sibling\'s special moment again', seoTitle: "How do I comfort the sibling whose big day got ruined?", answerBlock: "When the ADHD child could not hold regulation through the heightened emotion of someone else's celebration, the sibling lost their moment. Today, do not explain the ADHD. Just acknowledge the loss to the child whose day it was: 'That was your moment and it got interrupted. I am sorry. That was not fair.' The explanation can come another day. Right now they need their disappointment validated, not reasoned away." },
  { id: 'm61', type: 'moment', category: 'siblings', title: 'The whole family had to leave because one child could not cope', seoTitle: "What do I say when one child ends the whole outing?", answerBlock: "Leaving was the right call: the cost of staying had passed the benefit. But every family member experienced it differently and needs a different response, so do not process it in the car. Get everyone home safely first. Then speak to each child separately. The ADHD child needs to hear 'That was hard for your body.' The siblings need to hear 'I know that was not fair to you.'" },
  { id: 'p72', type: 'parent', category: 'siblings', title: 'We avoid normal family outings because of one child\'s triggers', seoTitle: "How do I start doing family outings again without a meltdown?", answerBlock: "Avoiding outings is a rational response to repeated bad experiences, but it is progressive: each one you skip removes a chance it could have gone well. Rebuild tolerance gradually. Plan one short, low-demand outing this week with a clear exit: 'We are going for twenty minutes. If it gets too much, we leave without drama.' A successful park trip teaches more than a full day that ends in crisis." },
  { id: 'p73', type: 'parent', category: 'siblings', title: 'I protected the sibling and now I feel like I rejected my ADHD child', seoTitle: "How do I repair when protecting one child hurt the other?", answerBlock: "Both children needed you in the same moment, and the intervention that protected one was felt as rejection by the other. That is structural, not a parenting failure, and the guilt is the impossibility of serving both. Later, go back to the ADHD child and say: 'I stopped you because your sibling was getting hurt. I love you. Both of those are true.' They need to hear both parts." },
  { id: 'p74', type: 'parent', category: 'siblings', title: 'I feel guilty when I enjoy time with my easier child', seoTitle: "Why do I feel guilty enjoying time with my easier child?", answerBlock: "That relief is physiology, not favouritism. Your nervous system recovers under lower demand, so enjoying the child who does not require constant executive function from you is your body resting, not a verdict on which child you love. Accept it without guilt. It only becomes a problem if it stops you investing in the harder relationship. Do one small, genuine thing with your ADHD child this week." },
  { id: 'm62', type: 'moment', category: 'partner', title: 'My partner yells and the meltdown gets worse', seoTitle: "What do I do when my partner yelling makes the meltdown worse?", answerBlock: "When your partner raises their voice and your child escalates, that is co-escalation: two nervous systems mirroring each other's alarm signals, each one triggering the next. As the third nervous system in the room, do not join, and do not correct your partner in front of the child. Signal a swap: 'I have got this. Take a minute.' The child needs one calm adult. Handle the disagreement later, privately." },
  { id: 'p75', type: 'parent', category: 'partner', title: 'My partner thinks I am too soft', seoTitle: "How do I convince my partner ADHD isn't just bad discipline?", answerBlock: "The real disagreement is about frame: whether ADHD is a discipline problem or a neurological one. Until you both share that frame, every accommodation looks like softness and every decision becomes a proxy battle. You will not win this mid-fight. On a calm evening, share one resource that explains why traditional discipline does not work for ADHD brains: 'I want us on the same page. Can you read this?'" },
  { id: 'p76', type: 'parent', category: 'partner', title: 'My partner blames me for our child\'s behaviour', seoTitle: "Why does my partner blame me for our child's behaviour?", answerBlock: "Nothing you did created the ADHD; parenting does not cause it. If the blame burns, that is because ADHD rejection sensitivity processes it at pain intensity, firing shame circuits alongside defensive anger. That does not make the accusation true. If your partner genuinely believes the behaviour is your fault, that is a relationship issue, not a parenting one, and couples therapy with an ADHD-informed therapist is practical, not dramatic." },
  { id: 'm63', type: 'moment', category: 'partner', title: 'We fight about whether this is ADHD or bad behaviour', seoTitle: "Is it ADHD or just bad behaviour and does it matter?", answerBlock: "It is both, which is why the argument stays circular: the ADHD explains why the behaviour happens, and it still needs addressing because your child has to learn. The disagreement is really about method, not about whether the behaviour matters. Stop fighting over why and move to how. Find the shared ground out loud: 'We both want them to learn. Let us talk about how, not why.'" },
  { id: 'm64', type: 'moment', category: 'partner', title: 'One of us stays calm and the other one escalates', seoTitle: "Why does one parent stay calm while the other loses it?", answerBlock: "Regulatory capacity is not character. It varies with depletion, trigger history, and how much time each parent spends with the child, so the calm parent may just have more left while the escalating one carries more of the daily load. Neither is better or worse. Discuss it later, without scorekeeping. 'What do you need from me when you are getting activated?' is more useful than 'Why did you yell?'" },
  { id: 'p77', type: 'parent', category: 'partner', title: 'My partner checks out and leaves me to handle the hard parts', seoTitle: "Why does my partner check out when parenting gets hard?", answerBlock: "When your partner disappears, it may be avoidance, overwhelm, or a belief that you handle it better. The pattern leaves you as the sole container for the hardest moments, and that is not sustainable. Name it without accusation: 'I need you to stay in the room even when it is hard. I cannot do this alone.' If it persists, it is a couples issue, not a parenting one." },
  { id: 'p78', type: 'parent', category: 'partner', title: 'We cannot talk about parenting without both getting defensive', seoTitle: "How do we talk about parenting without it becoming a fight?", answerBlock: "Sustained parenting stress makes both partners hypervigilant to criticism, so each conversation starts with both nervous systems already in defensive mode, before the topic is even raised. The topic is too hot to handle when you are both depleted. So schedule it instead: 'Saturday morning, coffee, fifteen minutes, one topic.' Remove the spontaneous ambush conversations that happen at 10pm, when neither of you has anything left to bring to it." },
  { id: 'k50', type: 'kid', category: 'social', title: 'Other kids do not like them and I can see why', seoTitle: "Why do other children pull away from my ADHD child?", answerBlock: "ADHD social processing runs at a different speed. Your child is louder, faster and more intense than the social norm, so other children pull away. The rejection is real, but your child is not bad, just running social software at a different pace. Social skills are teachable, and the teaching happens outside the social moment, not inside it. Role-play scenarios at home, and find the children who match their energy." },
  { id: 'k51', type: 'kid', category: 'social', title: 'They are too much for other children', seoTitle: "Why is my child too intense for other children to play with?", answerBlock: "ADHD arousal regulation means your child cannot dial their energy down to match the group. The intensity is not chosen, it is the baseline their nervous system runs at, and the same trait that exhausts other children also makes them passionate, creative and loyal. Do not suppress it. Change the context instead. Smaller groups and one-on-one playdates work better, along with activities where high energy is an asset." },
  { id: 'k52', type: 'kid', category: 'social', title: 'They boss other kids around and then feel rejected', seoTitle: "Why does my child boss other kids and then feel rejected?", answerBlock: "The bossiness is not a power grab, it is anxiety-driven control-seeking. Uncertainty feels intolerable to their nervous system, so controlling the game is an attempt to control the anxiety. When others do not comply, they feel rejected, not corrected. Teach the specific skill: 'Other kids want to choose too. Try asking what they want to play.' Role-play turn-taking, and the control impulse eases as social confidence grows." },
  { id: 'k53', type: 'kid', category: 'social', title: 'They cannot tell when the game has stopped being fun', seoTitle: "Why can't my child tell when a game stops being fun?", answerBlock: "Social cue reading is slower in ADHD. The facial expression, tone shift and body language that signal 'this is not fun anymore' were not processed in time, so from your child's point of view the game was still going while the other child had already stopped enjoying it. Teach one concrete cue they can watch for: 'When the other person stops laughing or starts pulling away, the game has changed.'" },
  { id: 'k54', type: 'kid', category: 'social', title: 'They keep annoying people after being asked to stop', seoTitle: "Why won't my child stop bugging people when asked?", answerBlock: "This is not defiance. The instruction to stop reached their auditory processing, but it did not reach their motor system before the next impulse fired, because in ADHD the braking system is slower than the accelerator. Verbal instructions alone may not land in time. Give them a concrete stop signal: a physical cue, a hand on the shoulder or a visual sign, which reaches the motor system faster than words." },
  { id: 'k55', type: 'kid', category: 'social', title: 'They are rude to adults and I feel humiliated', seoTitle: "Why is my ADHD child so rude to other adults?", answerBlock: "The rudeness was not calculated. ADHD verbal impulsivity means the thought became the spoken word before the social filter could engage, so the output ran faster than the assessment. Do not correct it in the moment, in front of the adult. Address it afterwards, and give the replacement, not just the criticism: 'The way that came across sounded rude. Next time, try saying it like this.'" },
  { id: 'k56', type: 'kid', category: 'social', title: 'They always need the last word', seoTitle: "Why does my ADHD child always need the last word?", answerBlock: "Perseverative speech means the conversational loop will not close until the emotional resolution their brain is chasing arrives, and it has not. They cannot stop because the feeling driving the words has not been discharged. Walking away is not losing. Say 'We are done talking about this for now,' then physically move to another space. The conversation ends when you stop participating, not when they agree to." },
  { id: 'k57', type: 'kid', category: 'social', title: 'They take over every conversation', seoTitle: "Why does my ADHD child take over every conversation?", answerBlock: "They are not dismissing people. The thought is at full volume in their head, and the impulse to speak fires faster than the awareness that someone else is talking, so they cannot hold the thought and wait for a turn. Teach the pause and give them a physical anchor, something to squeeze while they wait. Practise at home: 'Hold that thought for ten seconds.' The skill exists, it needs building." },
  { id: 'k58', type: 'kid', category: 'development', title: 'They are older now and the anger is bigger', seoTitle: "Why is my child's anger getting bigger as they get older?", answerBlock: "Emotional intensity scales with physical development, but the regulation skills have not kept pace. So the child who threw toys at five now punches walls at twelve: the feeling is bigger, the body is stronger, and the gap between the emotion and the capacity to manage it is widening. This is the point where professional support matters, not because you failed, but because closing that gap needs targeted intervention." },
  { id: 'k59', type: 'kid', category: 'development', title: 'They want to be treated older but cannot manage basic things', seoTitle: "Why does my child want independence but forget the basics?", answerBlock: "The desire for autonomy is age-appropriate; the executive function to run it is not. In ADHD, executive function age lags chronological age by 30 percent, so a twelve-year-old may be operating with the executive skills of an eight-year-old. Do not grant or refuse the freedom. Scaffold it: build the skill first, then extend the freedom. 'You can walk to school once you remember your bag three days in a row.'" },
  { id: 'k60', type: 'kid', category: 'development', title: 'They refuse supports because they feel babyish', seoTitle: "Why does my child refuse the tools that would help them?", answerBlock: "By adolescence, ADHD children are acutely aware of how they differ, so any support that highlights that difference gets rejected to protect their identity. The refusal is self-preservation, not defiance. Reframe the tool instead of forcing it. Match it to their self-concept, not their diagnosis: a phone reminder instead of a wall chart, and 'Athletes and pilots use checklists because they work,' instead of 'You need this because you forget.'" },
  { id: 'p79', type: 'parent', category: 'executive-function', title: 'Every routine still needs me to remember the routine', seoTitle: "How do I stop being my family's whole memory system?", answerBlock: "When the primary caregiver has ADHD, the household often lacks a neurotypical anchor to hold the systems together, so the whole executive-function load falls on a brain already at capacity. You cannot outsource all of it, but you can outsource some. Externalise everything you can into alarms, automated reminders, visual schedules and default routines. Each system that runs without your voice is one less demand on your depleted brain." },
];

